def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    supported = {1, 2, 4, 8}

    def aborts(row):
        outputs = row['outputs']
        inputs = row['inputs']
        return (
            outputs.get('al') == 1
            or inputs.get('nReset') == 0
            or inputs.get('rst') == 1
        )

    active_rises = edges(trace, 'active_command', 'rise')
    scl_changes = edges(trace, 'scl_oen', 'change')
    sda_changes = edges(trace, 'sda_oen', 'change')

    def accepted_active(row):
        inputs = row['inputs']
        return (
            row['edge'] in active_rises
            and inputs.get('ena') == 1
            and inputs.get('cmd') in supported
        )

    windows = after(
        trace,
        accepted_active,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborts
    )

    def control_activity(row):
        return (
            row['edge'] in scl_changes
            or row['edge'] in sda_changes
        )

    return worst([
        eventually(
            window,
            control_activity,
            strong=True,
            after_activation=True
        )
        for window in windows
    ])

def decide(trace):
    if not trace:
        return (None, None, 'no clock-edge samples; the requirement was not exercised')

    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o is not constant low, as required for open-drain control')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o is not constant low, as required for open-drain control')

    return (True, None, 'scl_o and sda_o remain constant low for all sampled states')

def decide(trace):
    def operating(row):
        outputs = row.get('outputs', {})
        return bool(outputs.get('in_idle')) or bool(outputs.get('active_command'))

    operating_rows = [r for r in trace if operating(r)]
    if not operating_rows:
        return (None, None, 'the module-operating activation never occurred: neither in_idle nor active_command was observed')

    for row in operating_rows:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o was not the constant low drive value')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o was not the constant low drive value')

    for row in operating_rows:
        outputs = row.get('outputs', {})
        if outputs.get('write_stable_high_phase') or outputs.get('read_sample_window'):
            if outputs.get('scl_oen') != 1:
                return (False, row.get('edge'), 'scl_oen was not 1, the released value for the active-low SCL output-enable control')
        if outputs.get('in_read_sequence'):
            if outputs.get('sda_oen') != 1:
                return (False, row.get('edge'), 'sda_oen was not 1, the released value for the active-low SDA output-enable control during the READ sequence')

    return (True, None, 'scl_o and sda_o remained constant low; observed release phases used active-low output-enable value 1')

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, edges, worst

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The command encoding is not supplied by an authoritative encoding table.
    # The declared probe identifies the commanded-operation situation without
    # asserting an invented numeric encoding.
    windows = after(
        trace,
        holds({'active_command': 1}),
        until=holds({'cmd_ack': 1}),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1}
        ])
    )

    scl_changes = edges(trace, 'scl_oen', 'change')
    sda_changes = edges(trace, 'sda_oen', 'change')

    def line_control_changes(row):
        return row['edge'] in scl_changes or row['edge'] in sda_changes

    return worst([
        eventually(
            window,
            line_control_changes,
            after_activation=True,
            strong=False
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def value(row, port):
        return row.get('outputs', {}).get(port,
               row.get('inputs', {}).get(port))

    def any_condition(conditions):
        def predicate(row):
            return any(all(value(row, port) == expected
                           for port, expected in condition.items())
                       for condition in conditions)
        return predicate

    windows = after(
        trace,
        lambda row: value(row, 'active_command') == 1
                    and value(row, 'ena') == 1,
        until=lambda row: value(row, 'cmd_ack') == 1,
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1}
        ])
    )

    def generated(window):
        scl_initial = window.value('scl_oen')
        sda_initial = window.value('sda_oen')
        return eventually(
            window,
            lambda row: (
                value(row, 'scl_oen') != scl_initial or
                value(row, 'sda_oen') != sda_initial
            ),
            after_activation=True,
            strong=False
        )

    return worst([
        generated(window) for window in windows
    ])

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def decide(trace):
    def reset_active(row):
        return row['inputs'].get('rst') == 1

    def reset_outputs(row):
        out = row['outputs']
        return (
            out.get('cmd_ack') == 0 and
            out.get('busy') == 0 and
            out.get('al') == 0 and
            out.get('dout') == 0 and
            out.get('scl_oen') == 1 and
            out.get('sda_oen') == 1
        )

    windows = after(trace, reset_active, until=WHILE_ACTIVE)
    return worst([
        throughout(w, reset_outputs, after_activation=False)
        for w in windows
    ])

def decide(trace):
    activations = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_inputs = prev['inputs']
        inputs = row['inputs']
        prev_outputs = prev['outputs']
        outputs = row['outputs']

        # The routed activation is a falling transition of nReset while the
        # controller is active and scl_oen is not already at reset idle high.
        reset_fell = prev_inputs.get('nReset') == 1 and inputs.get('nReset') == 0
        active = bool(prev_outputs.get('active_command'))
        not_already_reset = prev_outputs.get('scl_oen') != 1

        if reset_fell and active and not_already_reset:
            activations.append((i, row))
            if outputs.get('scl_oen') != 1:
                return (
                    False,
                    row['edge'],
                    'scl_oen did not change immediately to 1 when nReset was asserted low '
                    'while the controller was active; asynchronous reset initialization was required'
                )

    if not activations:
        return (
            None,
            None,
            'no qualifying nReset high-to-low transition occurred while the controller was active '
            'with scl_oen not already at reset idle high'
        )

    return (
        True,
        activations[0][1]['edge'],
        'scl_oen was 1 in the state immediately following each qualifying asynchronous nReset assertion'
    )

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

def decide(trace):
    def disabled_active(row):
        return (row['inputs'].get('ena') == 0 and
                row['outputs'].get('active_command') == 1)

    windows = after(trace, disabled_active, until=WHILE_ACTIVE)
    verdict = worst([
        throughout(w, lambda r: r['outputs'].get('cmd_ack') == 0,
                   after_activation=False)
        for w in windows
    ])

    if verdict[0] is False:
        return verdict
    if not windows or verdict[0] is None:
        return verdict

    enabled_completion = next(
        (r for r in trace
         if r['inputs'].get('ena') == 1 and
            r['outputs'].get('cmd_ack') == 1),
        None
    )
    if enabled_completion is None:
        return (None, None,
                'disabled active-command window was seen, but no ena-high cmd_ack completion was observed for the comparison case')

    return (True, enabled_completion['edge'],
            'cmd_ack remained low while an active command was disabled; ena-high completion evidence was observed')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def sig(row, name, default=False):
        return row.get('outputs', {}).get(name, default)

    def is_rise(rows, i, name):
        if i == 0:
            return False
        return sig(rows[i], name, 0) == 1 and sig(rows[i - 1], name, 0) == 0

    observations = []
    saw_short = False
    saw_long = False

    for i, row in enumerate(trace):
        # The real stimulus is the SDA transition.  The declared idle probe
        # names the bus-idle situation; inputs only qualify that situation.
        if i == 0:
            continue
        if not (inp(row, 'sda_i') == 0 and inp(trace[i - 1], 'sda_i') == 1):
            continue
        if sig(row, 'in_idle', False) != 1:
            continue
        if inp(row, 'ena') != 1 or inp(row, 'scl_i') != 1:
            continue
        if sig(row, 'busy', 0) != 0:
            continue

        clk_cnt = int(inp(row, 'clk_cnt', 0))
        interval = clk_cnt // 4

        # Measure the stimulus duration in edges, not compressed rows.
        j = i
        low_edges = 0
        while j < len(trace) and inp(trace[j], 'sda_i') == 0:
            low_edges += int(trace[j].get('held', 1))
            j += 1

        if interval > 0 and low_edges < interval:
            saw_short = True
            k = i
            bad = None
            while k < len(trace) and inp(trace[k], 'sda_i') == 0:
                if sig(trace[k], 'start_condition', False) or is_rise(trace, k, 'busy'):
                    bad = trace[k]
                    break
                k += 1
            if bad is not None:
                observations.append((False, bad.get('edge'),
                    'an SDA transition shorter than the stated floor(clk_cnt/4) filter interval produced a filtered START/busy response'))
            continue

        saw_long = True
        found = None
        k = i
        while k < len(trace):
            if sig(trace[k], 'start_condition', False) and is_rise(trace, k, 'busy'):
                found = trace[k]
                break
            if is_rise(trace, k, 'busy'):
                found = trace[k]
                break
            k += 1
        if found is None:
            observations.append((False, row.get('edge'),
                'an SDA transition lasting at least the stated filter interval produced no filtered START/busy response'))
        else:
            observations.append((True, found.get('edge'),
                'busy rose after the filtered START signature for a transition sampled at the interval derived from floor(clk_cnt/4)'))

    if not observations:
        return (None, None, 'the qualified SDA filter-interval experiment was not exercised')
    for ok, edge, detail in observations:
        if not ok:
            return (False, edge, detail)
    if not saw_short or not saw_long:
        return (None, None, 'only one side of the stated filter-interval distinction was exercised')
    return (True, None, 'short SDA excursions were filtered and sufficiently sampled excursions produced the routed busy response using floor(clk_cnt/4); zero uses every enabled clock')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def is_start_idle(row):
        return (
            row.get('inputs', {}).get('cmd') == 1
            and row.get('outputs', {}).get('in_idle') == 1
        )

    windows = after(trace, is_start_idle, until=TO_END)

    def start_effect(row):
        outputs = row.get('outputs', {})
        return (
            outputs.get('in_start_sequence') == 1
            and outputs.get('sda_oen') == 0
            and outputs.get('scl_oen') == 1
        )

    return worst([
        eventually(
            window,
            start_effect,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    def out(row, name):
        return row['outputs'].get(name)

    def changed_to(i, port, value):
        if i <= 0:
            return False
        return out(trace[i], port) == value and out(trace[i - 1], port) != value

    attempts = []
    for i, row in enumerate(trace):
        if (row['inputs'].get('ena') == 1
                and out(row, 'in_idle') == 1
                and out(row, 'clk_en_tick') == 1):
            attempts.append(i)

    if not attempts:
        return (None, None, 'no enabled idle acceptance point was observed')

    for start in attempts:
        din = trace[start]['inputs'].get('din')
        sda_seen = False
        scl_released = None

        for i in range(start + 1, len(trace)):
            if out(trace[i], 'sda_oen') == din:
                sda_seen = True

            if sda_seen and changed_to(i, 'scl_oen', 1):
                scl_released = i
                break

        if scl_released is None:
            continue

        for i in range(scl_released + 1, len(trace)):
            if changed_to(i, 'scl_oen', 0):
                return (
                    True,
                    trace[i]['edge'],
                    'WRITE command recognized by sda_oen following din, then '
                    'scl_oen releasing high and subsequently driving low'
                )

    return (
        None,
        None,
        'no WRITE output signature was observed; cmd encoding is unspecified '
        'because no authoritative cmd encoding table is provided'
    )

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def output(row, name):
        return row.get('outputs', {}).get(name)

    def input_value(row, name):
        return row.get('inputs', {}).get(name)

    write_rises = edges(trace, 'in_write_sequence', 'rise')

    windows = after(
        trace,
        lambda row: (
            row.get('edge') in write_rises
            and input_value(row, 'ena') == 1
        ),
        until=lambda row: output(row, 'cmd_ack') == 1,
        aborts=lambda row: (
            output(row, 'al') == 1
            or input_value(row, 'nReset') == 0
            or input_value(row, 'rst') == 1
        )
    )

    return worst([
        eventually(
            w,
            lambda row: (
                output(row, 'write_stable_high_phase') == 1
                and output(row, 'sda_oen') == w.value('din')
            ),
            after_activation=True,
            strong=False
        )
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def _holds(row, cond):
        return all(
            row.get('outputs', {}).get(port, row.get('inputs', {}).get(port)) == value
            for port, value in cond.items()
        )

    def _aborted(row):
        return (
            row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
        )

    # The symbolic WRITE encoding is not supplied by an authoritative
    # encoding table; the declared probe is the WRITE-operation signature.
    def _write_active(row):
        return (
            row.get('inputs', {}).get('ena') == 1
            and row.get('outputs', {}).get('in_write_sequence') == 1
        )

    windows = after(
        trace,
        _write_active,
        until=lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
        aborts=_aborted,
    )

    follows = True
    return worst([
        eventually(
            window,
            lambda row, window=window: (
                row.get('outputs', {}).get('sda_oen') == window.value('din')
            ),
            after_activation=follows,
            strong=True,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def stretched(row):
        return (row['inputs'].get('scl_i') == 0 and
                row['outputs'].get('slave_wait') == 1)

    def released(row):
        return row['outputs'].get('slave_wait') != 1

    stretch_windows = after(trace, stretched, until=released)
    if not stretch_windows:
        return (None, None, 'no external low was observed as a released-SCL filtered stretch')

    verdicts = []
    completed_stretches = 0
    for window in stretch_windows:
        if not window.closed or not window.rows:
            continue

        completed_stretches += 1
        verdicts.append(
            throughout(
                window,
                lambda r: not (
                    r['inputs'].get('scl_i') == 0 and
                    r['outputs'].get('slave_wait') == 1 and
                    r['outputs'].get('cmd_ack') == 1
                ),
                after_activation=False
            )
        )

        release_index = window.rows[-1]['index']
        after_release = after(
            trace,
            lambda r, release_index=release_index: r['index'] == release_index,
            until=TO_END
        )
        verdicts.append(
            eventually(
                after_release[0],
                lambda r: r['outputs'].get('cmd_ack') == 1,
                strong=True,
                after_activation=False
            )
        )

    if completed_stretches == 0:
        return (None, stretch_windows[0].edge,
                'scl_i low opened a stretch, but filtered SCL did not become high in the trace')

    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def probe(row, name):
        return bool(out(row, name, 0))

    activation_names = (
        'start_condition',
        'stop_condition',
        'arbitration_checking',
        'filtered_scl_rise',
    )
    if not any(probe(row, name) for row in trace for name in activation_names):
        return (None, None, 'sda_i protocol-processing activation never occurred')

    last_busy_event = -1
    last_al_event = -1
    last_dout_event = -1
    previous = None

    for i, row in enumerate(trace):
        edge = row.get('edge')

        start = probe(row, 'start_condition')
        stop = probe(row, 'stop_condition')
        arbitration = probe(row, 'arbitration_checking')
        scl_rise = probe(row, 'filtered_scl_rise')
        read_window = probe(row, 'read_sample_window')

        if start or stop:
            last_busy_event = i
        if arbitration or stop:
            last_al_event = i
        if scl_rise and read_window:
            last_dout_event = i

        if previous is not None:
            raw_sda_changed = inp(row, 'sda_i') != inp(previous, 'sda_i')
            busy_changed = out(row, 'busy') != out(previous, 'busy')
            al_asserted = not bool(out(previous, 'al')) and bool(out(row, 'al'))
            dout_changed = out(row, 'dout') != out(previous, 'dout')

            if raw_sda_changed and busy_changed and not (start or stop):
                return (False, edge, 'busy changed on a raw sda_i transition without a filtered START/STOP probe')
            if raw_sda_changed and al_asserted and not (arbitration or stop):
                return (False, edge, 'al asserted on a raw sda_i transition without a filtered arbitration/STOP context')
            if raw_sda_changed and dout_changed and not (scl_rise and read_window):
                return (False, edge, 'dout changed on a raw sda_i transition without a filtered READ sampling edge')

            if busy_changed and last_busy_event < 0:
                return (False, edge, 'busy changed before any filtered START/STOP processing event')
            if al_asserted and last_al_event < 0:
                return (False, edge, 'al asserted before any declared filtered arbitration/STOP processing context')
            if dout_changed and last_dout_event < 0:
                return (False, edge, 'dout changed before a filtered SCL rising edge in the READ sampling window')

        previous = row

    return (True, None, 'sda_i-dependent output changes were causally preceded by declared filtered protocol-processing events')

def decide(trace):
    active_start = None
    completed = 0
    last_completion_edge = None
    saw_unknown_pulse = False

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    def active(row):
        return row.get('outputs', {}).get('active_command') == 1

    def ack(row):
        return row.get('outputs', {}).get('cmd_ack') == 1

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        if reset_active(row):
            active_start = None
            continue

        if active_start is None:
            if (not active(prev) and active(row)
                    and row.get('inputs', {}).get('ena') == 1):
                active_start = i
            continue

        if active(prev) and not active(row):
            completed += 1
            last_completion_edge = row.get('edge')

            if not ack(row):
                return (False, row.get('edge'),
                        'cmd_ack was low when the active START, STOP, READ, or WRITE command finished')

            if ack(prev):
                return (False, row.get('edge'),
                        'cmd_ack was already asserted before the command finished')

            width = row.get('held', 1)
            j = i + 1
            while j < len(trace) and ack(trace[j]):
                width += trace[j].get('held', 1)
                j += 1

            if width != 1:
                return (False, row.get('edge'),
                        f'cmd_ack was asserted for {width} edges; the requirement states one clk cycle')

            if j == len(trace):
                saw_unknown_pulse = True

            active_start = None

    if completed == 0:
        return (None, None,
                'no enabled command completion was observed; active_command never completed')

    if saw_unknown_pulse:
        return (None, last_completion_edge,
                'the command completed and cmd_ack was high for one observed edge, but the trace ended before its deassertion')

    return (True, last_completion_edge,
            f'{completed} command completion(s) had a one-clock cmd_ack pulse')

def decide(trace):
    from specflow.refmodel.temporal import edges, runs

    def value(row, name):
        return row.get('outputs', {}).get(name)

    def is_active(row):
        return value(row, 'active_command') == 1

    def is_idle(row):
        return value(row, 'in_idle') == 1

    # A command finishes when the declared active-command situation changes
    # to the declared idle situation.  This is a transition, not a fixed
    # number of states after the command input.
    completion_edges = set()
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if (is_active(previous) and is_idle(current)
                and value(current, 'al') != 1):
            completion_edges.add(current['edge'])

    if not completion_edges:
        return (None, None,
                'no non-aborted START, STOP, READ, or WRITE command completion occurred')

    ack_rises = edges(trace, 'cmd_ack', 'rise')
    exact_runs = runs(trace, 'cmd_ack', value=1, at_least=1, at_most=1)
    long_runs = runs(trace, 'cmd_ack', value=1, at_least=2)

    undecided = []
    for edge in sorted(completion_edges):
        row = next(r for r in trace if r['edge'] == edge)

        if value(row, 'cmd_ack') != 1:
            return (False, edge,
                    'cmd_ack was not asserted when the command finished')

        if edge not in ack_rises:
            return (False, edge,
                    'cmd_ack was already high before the command finished; it was not asserted for that completion')

        if edge in long_runs:
            return (False, edge,
                    'cmd_ack remained asserted for at least two clk edges; the requirement states one `clk` cycle')

        if edge in exact_runs:
            continue

        # A bounded run that has not ended before trace termination cannot
        # establish whether the one-clock duration was honoured.
        undecided.append(edge)

    if undecided:
        return (None, undecided[0],
                'cmd_ack asserted at completion, but the trace ended before its one-`clk`-cycle duration could be confirmed')

    return (True, sorted(completion_edges)[-1],
            f'{len(completion_edges)} command completion(s) each produced a one-`clk`-cycle cmd_ack pulse')

def decide(trace):
    activations = [
        r for r in trace
        if r.get('inputs', {}).get('ena') == 1
        and r.get('inputs', {}).get('scl_i') == 1
        and r.get('outputs', {}).get('filtered_scl_rise') == 1
    ]
    if not activations:
        return (None, None, 'filtered_scl_rise never occurred with filtering enabled and SCL externally high')

    for row in activations:
        dout = row.get('outputs', {}).get('dout')
        sda = row.get('inputs', {}).get('sda_i')
        if dout != sda:
            return (
                False,
                row.get('edge'),
                f"dout was {dout} at filtered_scl_rise, expected the sampled SDA value {sda}"
            )

    return (
        True,
        activations[-1].get('edge'),
        f'dout matched the sampled SDA value at {len(activations)} filtered SCL rising edge(s)'
    )

def decide(trace):
    if not trace:
        return (None, None, 'the module never produced an observation')

    for row in trace:
        value = row['outputs'].get('scl_o')
        if value != 0:
            return (False, row['edge'], f"scl_o was {value}, expected constant-low value 0")

    return (True, None, 'scl_o remained constantly low at 0 throughout all observations')

def decide(trace):
    low_rows = [
        row for row in trace
        if row['outputs']['scl_oen'] == 0
