def decide(trace):
    from specflow.refmodel.temporal import edges

    if not trace:
        return (None, None, 'no states were observed for raw-input synchronization')

    scl_changes = edges(trace, 'scl_i', 'change')
    sda_changes = edges(trace, 'sda_i', 'change')
    change_edges = scl_changes | sda_changes
    immediate_failure = None
    positive_evidence = None

    # A raw transition must not cause an immediate dout change.  The
    # comparison is against the preceding distinct state, not a fixed clock
    # count; this detects a bypass of the synchronization path without
    # asserting any implementation-specific latency.
    for i, row in enumerate(trace):
        if row['edge'] not in change_edges or row['inputs'].get('ena') != 1:
            continue
        if i > 0:
            before = trace[i - 1]['outputs'].get('dout')
            now = row['outputs'].get('dout')
            if before is not None and now is not None and now != before:
                immediate_failure = (row['edge'], 'raw scl_i or sda_i transition changed dout immediately')
                break

    if immediate_failure is not None:
        return (False, immediate_failure[0], immediate_failure[1])

    # Look for the route's positive case: a raw SDA value remains stable
    # through a qualifying filtered SCL rising edge while enabled, and dout
    # later reaches that value.  No number of intervening states is imposed.
    for i, row in enumerate(trace):
        if row['edge'] not in sda_changes or row['inputs'].get('ena') != 1:
            continue
        target = row['inputs'].get('sda_i')
        old_dout = row['outputs'].get('dout')
        rise_i = None
        for j in range(i + 1, len(trace)):
            if trace[j]['inputs'].get('sda_i') != target:
                break
            if (trace[j]['inputs'].get('ena') == 1 and
                    trace[j]['outputs'].get('filtered_scl_rise') == 1):
                rise_i = j
                break
        if rise_i is None:
            continue
        for k in range(rise_i + 1, len(trace)):
            if trace[k]['inputs'].get('sda_i') != target:
                break
            if trace[k]['outputs'].get('dout') == target:
                if old_dout != target:
                    positive_evidence = trace[k]['edge']
                break
        if positive_evidence is not None:
            break

    if positive_evidence is not None:
        return (True, positive_evidence, 'dout reflected stable raw sda_i after a filtered SCL rising edge; raw transitions did not immediately change dout')
    return (None, None, 'the route through dout did not provide both non-immediate and post-synchronization evidence')

def decide(trace):
    attempts = []

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        # A raw SDA transition while SCL is high is the route's
        # START/STOP-shaped activation.  Inputs qualify the situation only.
        if inp(row, 'ena') != 1 or inp(row, 'scl_i') != 1:
            continue
        if inp(prev, 'scl_i') != 1:
            continue
        if inp(prev, 'sda_i') == inp(row, 'sda_i'):
            continue

        start_edge = row['edge']
        baseline_busy = out(prev, 'busy')
        sample_seen = False
        saw_busy_change_after_sample = False
        aborted = False

        for j in range(i, len(trace)):
            current = trace[j]

            if (inp(current, 'nReset') == 0 or
                    inp(current, 'rst') == 1):
                aborted = True
                break

            busy_changed = False
            if j > 0:
                busy_changed = out(current, 'busy') != out(trace[j - 1], 'busy')

            # A response on the activation state, or before the first
            # sampling opportunity, bypasses the filter cadence.
            if busy_changed and not sample_seen:
                attempts.append((False, current['edge'],
                                 'busy changed before filter sampling admitted the raw SDA transition'))
                break

            if out(current, 'filter_sample_event') == 1:
                sample_seen = True

            if sample_seen and busy_changed:
                saw_busy_change_after_sample = True
                attempts.append((True, current['edge'],
                                 'busy changed only after a filter sampling event; raw transition edge was ' + str(start_edge)))
                break
        else:
            if not aborted and sample_seen and not saw_busy_change_after_sample:
                attempts.append((None, None,
                                 'filter sampling occurred but no routed busy response was observed'))

        if aborted:
            attempts.append((None, None,
                             'raw transition attempt was aborted by reset before the filter response could be observed'))

    if not attempts:
        return (None, None, 'no enabled START- or STOP-shaped raw SDA transition while SCL was high')

    for ok, edge, detail in attempts:
        if ok is False:
            return (False, edge, detail)

    for ok, edge, detail in attempts:
        if ok is True:
            return (True, edge, detail)

    return (None, None, 'the raw transition was not shown to be admitted and routed to busy')

