    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    def rises_at(i, port):
        if i == 0:
            return False
        return out(trace[i - 1], port) == 0 and out(trace[i], port) == 1

    positive = []
    negative = []
    for i, row in enumerate(trace):
        if reset_active(row):
            continue
        if row.get('inputs', {}).get('ena') != 1:
            continue
        if out(row, 'filter_sample_event') != 1:
            continue
        if out(row, 'start_condition') == 1:
            positive.append(i)
        else:
            negative.append(i)

    if not positive or not negative:
        return (None, None,
                'both majority-filtered START and non-START filter-sample cases are required; '
                'the trace exercised only one side')

    for i in positive:
        if not rises_at(i, 'busy'):
            return (False, trace[i]['edge'],
                    'at a filter sample where the three-sample histories produce the '
                    'majority-filtered START condition, busy did not rise')

    for i in negative:
        if rises_at(i, 'busy'):
            return (False, trace[i]['edge'],
                    'at a filter sample where the three-sample histories do not produce '
                    'the majority-filtered START condition, busy rose')

    return (True, trace[positive[0]]['edge'],
            'majority-filtered START and non-START sample cases both produced the required busy transition difference')

