        prev_dout = trace[i - 1].get('outputs', {}).get('dout') if i > 0 else None

        # A raw transition at the sampling observation is the routed
        # late-transition case.  The captured path must retain its prior value.
        if (i > 0 and prev_sda is not None and prev_dout is not None
                and sda != prev_sda and sda != prev_dout):
