    for a in range(len(transactions)):
        for b in range(a + 1, len(transactions)):
            x = transactions[a]
            y = transactions[b]
            same_context = (x['cmd'] == y['cmd'] and
                            x['din'] == y['din'] and
                            x['scl_i'] == y['scl_i'] and
                            x['sda_i'] == y['sda_i'])
            if not same_context or x['clk_cnt'] == y['clk_cnt']:
                continue
            low, high = (x, y) if x['clk_cnt'] < y['clk_cnt'] else (y, x)
            comparisons.append((low, high))
