                return (False, high['ack_edge'],
                        'with the same opaque command context, increasing clk_cnt did not delay cmd_ack; '
                        'the required counter timing relationship was not observed')

    if not starts:
        return (None, None, 'no accepted supported command was observed')
    if not transactions:
        return (None, None, 'accepted command attempts were incomplete or aborted before cmd_ack')
    if not comparisons:
        return (None, None,
                'no two non-aborted matching command transactions with different clk_cnt values were observed; '
                'the clk_cnt-dependent timing relationship cannot be decided')
    return (True, None,
            'for every comparable non-aborted command pair, the larger clk_cnt delayed cmd_ack; '
            'no exact latency was required')

