    sync1 = 1
    sync2 = 1
    hist = [1, 1, 1]
    saw_rise = False
    last_rise_edge = None

    def majority(bits):
        return 1 if sum(bits) >= 2 else 0

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        held = row.get('held', 1)
        try:
            held = max(1, int(held))
        except (TypeError, ValueError):
            held = 1

        for step in range(held):
            if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
                sync1 = 1
                sync2 = 1
                hist = [1, 1, 1]
                continue

            old_sync1 = sync1
            sync1 = 1 if inputs.get('sda_i') else 0
            sync2 = old_sync1

            if outputs.get('filter_sample_event') == 1:
                hist = [hist[1], hist[2], sync2]

            if outputs.get('filtered_scl_rise') == 1 and step == 0:
                saw_rise = True
                last_rise_edge = row.get('edge')
                expected = majority(hist)
                actual = outputs.get('dout')
                if actual != expected:
                    return (
                        False,
                        row.get('edge'),
                        f"at filtered SCL rising edge, dout was {actual!r}; expected filtered SDA majority value {expected}"
