    verdicts = []
    exact_pulses = runs(
        trace,
        'cmd_ack',
        value=1,
        at_least=1,
        at_most=1,
    )

    for w in windows:
        completion = eventually(
            w,
            lambda r: (
                r['outputs'].get('cmd_ack') == 1
                and r['outputs'].get('in_idle') == 1
            ),
            after_activation=follows,
            strong=True,
