        )

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    windows = after(
        trace,
        applies,
        until=lambda r: r.get('outputs', {}).get('cmd_ack') == 1,
        aborts=reset_active,
    )

    verdicts = []
    for window in windows:
        arrival = eventually(
            window,
            lambda r: r.get('outputs', {}).get('cmd_ack') == 1,
            strong=True,
            after_activation=True,
        )
        if arrival[0] is not True:
            verdicts.append(arrival)
            continue

