        high_edges = 0
        pos = ack_pos
        while pos < len(trace):
            row = trace[pos]
            if row.get('outputs', {}).get('cmd_ack') != 1:
                break
            high_edges += row.get('held', 1)
            pos += 1

        if high_edges != 1:
            verdicts.append((
                False,
                ack_row.get('edge'),
                f"cmd_ack was high for {high_edges} edges; the requirement says 'asserted for exactly one `clk` cycle'",
            ))
        elif pos >= len(trace):
            verdicts.append((
                None,
                ack_row.get('edge'),
                "cmd_ack completed a one-edge observed pulse, but the trace ended before its return low",
            ))
        else:
            verdicts.append((
                True,
                ack_row.get('edge'),
                "cmd_ack was high for exactly one `clk` cycle at sequence completion and then returned low",
            ))

    return worst(verdicts)

