def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, sequence, worst

    def holds_state(scl, sda):
        def predicate(row):
            out = row['outputs']
            return out.get('scl_oen') == scl and out.get('sda_oen') == sda
        return predicate

    def any_condition(alternatives):
        def predicate(row):
            out = row['outputs']
            inp = row['inputs']
            return any(
                all(out.get(port, inp.get(port)) == value
                    for port, value in condition.items())
                for condition in alternatives
            )
        return predicate

    supported = {1, 2, 4, 8}

    def applies(row):
        return row['inputs'].get('ena') == 1 and row['inputs'].get('cmd') in supported

    windows = after(
        trace,
        applies,
        until=any_condition([{'cmd_ack': 1}]),
        aborts=any_condition([{'al': 1}, {'nReset': 0}, {'rst': 1}])
    )

    def expected_sequence(window):
        cmd = window.value('cmd')
        din = window.value('din')

        if cmd == 1:          # START: release both, drive SDA, then drive SCL
            states = [holds_state(1, 1), holds_state(1, 0), holds_state(0, 0)]
            name = 'START'
        elif cmd == 2:        # STOP: drive both, release SCL, then release SDA
            states = [holds_state(0, 0), holds_state(1, 0), holds_state(1, 1)]
            name = 'STOP'
        elif cmd == 8:        # READ: release both, then pull SCL low
            states = [holds_state(1, 1), holds_state(0, 1)]
            name = 'READ'
        else:                  # WRITE: set SDA from din, release SCL, then pull SCL low
            sda_enable = 0 if din == 0 else 1
            states = [holds_state(0, sda_enable), holds_state(0, 0)]
            name = 'WRITE'

        return sequence(
            window,
            *states,
            strong=True,
            after_activation=True
        )

    return worst([expected_sequence(w) for w in windows])

