def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def probe(row, name):
        return bool(out(row, name))

    def starts(name):
        result = []
        previous = False
        for i, row in enumerate(trace):
            here = probe(row, name)
            if here and not previous:
                result.append(i)
            previous = here
        return result

    def edge_after(port, value, start, direction):
        previous = out(trace[start], port)
        for i in range(start + 1, len(trace)):
            current = out(trace[i], port)
            if direction == 'rise' and previous != 1 and current == 1:
                return i
            if direction == 'fall' and previous != 0 and current == 0:
                return i
            previous = current
        return None

    def ordered(start, requirements):
        pos = start
        for requirement in requirements:
            found = None
            for i in range(pos, len(trace)):
                if all(out(trace[i], p) == v for p, v in requirement.items()):
                    found = i
                    break
            if found is None:
                return None
            pos = found + 1
        return pos - 1

    verdicts = []

    for start in starts('in_start_sequence'):
        end = ordered(start, [
            {'sda_oen': 1, 'scl_oen': 1},
            {'sda_oen': 0},
            {'scl_oen': 0}
        ])
        if end is None:
            verdicts.append((False, trace[start].get('edge'),
                             'START sequence did not release both lines, then drive SDA low and SCL low'))
        else:
            ack = next((i for i in range(end + 1, len(trace))
                        if out(trace[i], 'cmd_ack') == 1), None)
            if ack is None:
                verdicts.append((False, trace[end].get('edge'),
                                 'START sequence completed its line phases but no command-completion indication appeared'))
            else:
                verdicts.append((True, trace[ack].get('edge'),
                                 'START output-enable ordering and command completion observed'))

    for start in starts('in_stop_sequence'):
        end = ordered(start, [
            {'sda_oen': 0},
            {'scl_oen': 1},
            {'sda_oen': 1}
        ])
        if end is None:
            verdicts.append((False, trace[start].get('edge'),
                             'STOP sequence did not drive SDA low, release SCL, then release SDA'))
        else:
            ack = next((i for i in range(end + 1, len(trace))
                        if out(trace[i], 'cmd_ack') == 1), None)
            if ack is None:
                verdicts.append((False, trace[end].get('edge'),
                                 'STOP sequence completed its line phases but no command-completion indication appeared'))
            else:
                verdicts.append((True, trace[ack].get('edge'),
                                 'STOP output-enable ordering and command completion observed'))

    for start in starts('in_write_sequence'):
        din = trace[start].get('inputs', {}).get('din')
        desired_sda = 0 if din == 0 else 1 if din == 1 else None
        if desired_sda is None:
            continue
        end = ordered(start, [
            {'sda_oen': desired_sda},
            {'scl_oen': 1},
            {'scl_oen': 0}
        ])
        if end is None:
            verdicts.append((False, trace[start].get('edge'),
                             'WRITE sequence did not set SDA from din, release SCL, then pull SCL low'))
        else:
            ack = next((i for i in range(end + 1, len(trace))
                        if out(trace[i], 'cmd_ack') == 1), None)
            if ack is None:
                verdicts.append((False, trace[end].get('edge'),
                                 'WRITE sequence completed its line phases but no command-completion indication appeared'))
            else:
                verdicts.append((True, trace[ack].get('edge'),
                                 'WRITE output-enable ordering and command completion observed'))

    for start in starts('in_read_sequence'):
        end = ordered(start, [
            {'sda_oen': 1},
            {'scl_oen': 1},
            {'scl_oen': 0}
        ])
        if end is None:
            verdicts.append((False, trace[start].get('edge'),
                             'READ sequence did not release SDA, release SCL, then pull SCL low'))
        else:
            ack = next((i for i in range(end + 1, len(trace))
                        if out(trace[i], 'cmd_ack') == 1), None)
            if ack is None:
                verdicts.append((False, trace[end].get('edge'),
                                 'READ sequence completed its line phases but no command-completion indication appeared'))
            else:
                verdicts.append((True, trace[ack].get('edge'),
                                 'READ output-enable ordering and command completion observed'))

    for start in starts('start_condition'):
        edge = edge_after('busy', 1, start, 'rise')
        if edge is None:
            verdicts.append((False, trace[start].get('edge'),
                             'filtered START condition occurred but busy did not rise'))
        else:
            verdicts.append((True, trace[edge].get('edge'),
                             'busy rose after filtered START detection'))

    for start in starts('stop_condition'):
        edge = edge_after('busy', 0, start, 'fall')
        if edge is None:
            verdicts.append((False, trace[start].get('edge'),
                             'filtered STOP condition occurred but busy did not clear'))
        else:
            verdicts.append((True, trace[edge].get('edge'),
                             'busy cleared after filtered STOP detection'))

    for start in starts('arbitration_checking'):
        row = trace[start]
        if row.get('inputs', {}).get('din') == 1 and row.get('inputs', {}).get('sda_i') == 0:
            edge = edge_after('al', 1, start, 'rise')
            if edge is None:
                verdicts.append((False, row.get('edge'),
                                 'released-high WRITE arbitration condition occurred but al did not assert'))
            else:
                verdicts.append((True, trace[edge].get('edge'),
                                 'arbitration loss asserted for released-high WRITE with SDA low'))

    if not verdicts:
        return (None, None, 'no supported command or relevant bus-condition probe occurred while enabled')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return (True, verdicts[-1][1], 'all observed supported-command and bus-status obligations passed')

