    checked = False
    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        active = outputs.get('active_command') == 1
        write = outputs.get('in_write_sequence') == 1
        read_sample = outputs.get('read_sample_window') == 1
        slave_wait = outputs.get('slave_wait') == 1

        if not (active or write or read_sample or slave_wait):
            continue
        checked = True

        if write and 'din' in inputs:
            expected = inputs['din']
            actual = outputs.get('sda_oen')
            if actual != expected:
                return (False, row.get('edge'),
                        f'active-low SDA enable must equal din during WRITE: expected sda_oen={expected}, got {actual}')

        if read_sample:
            if outputs.get('sda_oen') != 1:
                return (False, row.get('edge'),
                        'SDA must be released during the declared READ sample window: expected sda_oen=1')
            if outputs.get('scl_oen') != 1:
                return (False, row.get('edge'),
                        'SCL must be released during the declared READ sample window: expected scl_oen=1')

        if slave_wait and outputs.get('scl_oen') != 1:
            return (False, row.get('edge'),
                    'SCL must remain released while the declared slave-wait condition is active: expected scl_oen=1')

    if not checked:
