def decide(trace):
    transitions = []
    for port in ('scl_oen', 'sda_oen'):
        previous = None
        for row in trace:
            value = row.get('outputs', {}).get(port)
            if value not in (0, 1):
                previous = value
                continue
            if previous in (0, 1) and value != previous:
                transitions.append((row.get('edge'), port, value))
            previous = value

    if not transitions:
        return (None, None,
                'no scl_oen or sda_oen control-level transition was exercised; reset-time release is not an action')

    edge, port, value = transitions[0]
    levels = ', '.join(f'{p}={v}' for _, p, v in transitions)
    return (True, edge,
            f'observed output-enable transitions into the specified active-low control levels: {levels}')

