    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    def active_paused(row):
        return (
            row['inputs'].get('ena') == 0
            and row['outputs'].get('active_command') == 1
        )

    aborts = any_of([{'nReset': 0}, {'rst': 1}])
    windows = after(
        trace,
        active_paused,
        until=WHILE_ACTIVE,
        aborts=aborts,
    )

    if not windows:
        return (None, None, 'no active command was observed while ena was low')

    low_verdicts = [
        throughout(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 0,
            after_activation=False,
        )
        for window in windows
    ]
    low_result = worst(low_verdicts)
    if low_result[0] is False:
        return low_result
    if low_result[0] is None:
        return low_result

    for window in windows:
        if not window.rows or not window.closed:
            return (None, window.edge, 'ena-low pause window was incomplete')

        end_index = window.rows[-1]['index']
        reenabled = False
        reenable_edge = None
        for row in trace:
            if row['index'] <= end_index:
                continue
            if row['inputs'].get('ena') == 1:
                reenabled = True
                reenable_edge = row['edge']
                break

        if not reenabled:
            return (None, window.edge, 'ena was not re-enabled after the paused command')

        completed = None
        for row in trace:
            if row['edge'] < reenable_edge:
                continue
            if row['inputs'].get('ena') == 1 and row['outputs'].get('cmd_ack') == 1:
                completed = row
                break

        if completed is None:
            return (None, reenable_edge, 'no ordinary cmd_ack completion was observed after ena was re-enabled')

    return (True, None, 'cmd_ack stayed low while ena was low and completion resumed after ena was re-enabled')

