def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def probe(row, name, default=False):
        return out(row, name, default)

    def held(row):
        return int(row.get('held', 1))

    short_seen = False
    long_seen = False
    failures = []
    failure_edges = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        # Anchor the controlled SDA high-to-low action, rather than matching
        # the resting low level.  The route requires an idle, enabled bus with
        # no active command and SCL high.
        falling_sda = inp(prev, 'sda_i') == 1 and inp(row, 'sda_i') == 0
        qualified = (
            falling_sda and
            inp(row, 'scl_i') == 1 and
            inp(row, 'ena') == 1 and
            probe(row, 'in_idle') and
            not probe(row, 'active_command') and
            out(row, 'busy') == 0
        )
        if not qualified:
            continue

        clk_cnt = int(inp(row, 'clk_cnt', 0))
        interval = max(1, clk_cnt // 4)

        # Find the end of this controlled low interval.  State compression
        # means duration is the sum of held edges, not the number of rows.
        j = i
        low_edges = 0
        while j < len(trace) and inp(trace[j], 'sda_i') == 0:
            low_edges += held(trace[j])
            j += 1

        # A pulse shorter than the stated sampling interval is the negative
        # side of the routed signature.
        if low_edges < interval:
            short_seen = True
            k = i
            while k < len(trace):
                if k > i and inp(trace[k], 'sda_i') == 1:
                    break
                if out(trace[k], 'busy') == 1:
                    failures.append(
                        'a SDA transition shorter than the stated floor(clk_cnt/4) filter interval changed busy'
                    )
                    failure_edges.append(trace[k].get('edge'))
                    break
                k += 1
            continue

        # Require a clearly sampled low interval.  The filter uses three
        # sample histories, so three derived intervals provide an unambiguous
        # positive exercise without imposing a response latency.
        if low_edges >= 3 * interval:
            long_seen = True
            k = i + 1
            saw_busy = False
            while k < len(trace):
                r = trace[k]
                if out(r, 'busy') == 1:
                    saw_busy = True
                    break
                if inp(r, 'sda_i') == 1 or inp(r, 'ena') != 1 or probe(r, 'active_command'):
                    break
                k += 1
            if not saw_busy and k < len(trace):
                failures.append(
                    'a SDA transition held for at least three floor(clk_cnt/4) intervals did not make busy rise'
                )
                failure_edges.append(row.get('edge'))

    if failures:
        return (False, failure_edges[0], failures[0])
    if not short_seen or not long_seen:
        return (None, None, 'the routed filter-interval signature was not exercised on both brief and sufficiently sampled SDA transitions')
    return (True, None, 'busy distinguished SDA transitions shorter than floor(clk_cnt/4) from transitions held for three derived filter intervals; zero interval used one enabled-clock interval')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def probe(row, name, default=False):
        return out(row, name, default)

    def held(row):
        return int(row.get('held', 1))

    activation_seen = False
    observations = []

    for i, row in enumerate(trace):
        # in_idle is the declared probe naming the state in which the
        # controlled input experiment is licensed.  Inputs only qualify it.
        active = (
            probe(row, 'in_idle', False) and
            inp(row, 'ena') == 1 and
            inp(row, 'scl_i') == 1 and
            out(row, 'busy') == 0
        )
        if not active:
            continue
        activation_seen = True
        clk_cnt = int(inp(row, 'clk_cnt', 0))
        interval = clk_cnt // 4

        # A filtered START is the positive routed signature.  Do not require
        # it to occur at a particular edge; the specification fixes the
        # sampling interval, not the end-to-end latency.
        if probe(row, 'start_condition', False):
            j = i
            while j < len(trace):
                if out(trace[j], 'busy') == 1:
                    observations.append((True, trace[j].get('edge'),
                                         'busy rose after filtered START detection'))
                    break
                if j > i and not probe(trace[j], 'in_idle', False):
                    observations.append((False, trace[j].get('edge'),
                                         'busy did not rise when the filtered START became possible'))
                    break
                j += 1

        # Find a raw SDA-low run that starts in the qualified idle situation.
        # This is an observation of the stimulus, not an obligation on sda_i.
        if inp(row, 'sda_i') != 0:
            continue
        if i > 0 and inp(trace[i - 1], 'sda_i') == 0:
            continue

        low_edges = 0
        j = i
        while j < len(trace) and inp(trace[j], 'sda_i') == 0:
            low_edges += held(trace[j])
            j += 1

        # For a nonzero derived interval, a shorter input excursion must not
        # produce the routed busy response.  For interval zero there is no
        # licensed shorter-than-one-edge case.
        if interval > 0 and low_edges < interval:
            k = i
            while k < j:
                if out(trace[k], 'busy') == 1:
                    observations.append((False, trace[k].get('edge'),
                                         'a SDA interval shorter than floor(clk_cnt/4) changed busy'))
                    break
                k += 1

    if not activation_seen:
        return (None, None, 'the qualified in_idle filter-sampling situation never occurred')
    if not observations:
        return (None, None, 'no filtered START or shorter-than-floor(clk_cnt/4) SDA signature was observed')

    for ok, edge, detail in observations:
        if not ok:
            return (False, edge, detail)
    return (True, None, 'busy responses matched the filter interval derived from floor(clk_cnt/4); zero interval uses every enabled clock')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def sig(row, name, default=False):
        return row.get('outputs', {}).get(name, default)

    def is_rise(rows, i, name):
        if i == 0:
            return False
        return sig(rows[i], name, 0) == 1 and sig(rows[i - 1], name, 0) == 0

    observations = []
    saw_short = False
    saw_long = False

    for i, row in enumerate(trace):
        # The real stimulus is the SDA transition.  The declared idle probe
        # names the bus-idle situation; inputs only qualify that situation.
        if i == 0:
            continue
        if not (inp(row, 'sda_i') == 0 and inp(trace[i - 1], 'sda_i') == 1):
            continue
        if sig(row, 'in_idle', False) != 1:
            continue
        if inp(row, 'ena') != 1 or inp(row, 'scl_i') != 1:
            continue
        if sig(row, 'busy', 0) != 0:
            continue

        clk_cnt = int(inp(row, 'clk_cnt', 0))
        interval = clk_cnt // 4

        # Measure the stimulus duration in edges, not compressed rows.
        j = i
        low_edges = 0
        while j < len(trace) and inp(trace[j], 'sda_i') == 0:
            low_edges += int(trace[j].get('held', 1))
            j += 1

        if interval > 0 and low_edges < interval:
            saw_short = True
            k = i
            bad = None
            while k < len(trace) and inp(trace[k], 'sda_i') == 0:
                if sig(trace[k], 'start_condition', False) or is_rise(trace, k, 'busy'):
                    bad = trace[k]
                    break
                k += 1
            if bad is not None:
                observations.append((False, bad.get('edge'),
                    'an SDA transition shorter than the stated floor(clk_cnt/4) filter interval produced a filtered START/busy response'))
            continue

        saw_long = True
        found = None
        k = i
        while k < len(trace):
            if sig(trace[k], 'start_condition', False) and is_rise(trace, k, 'busy'):
                found = trace[k]
                break
            if is_rise(trace, k, 'busy'):
                found = trace[k]
                break
            k += 1
        if found is None:
            observations.append((False, row.get('edge'),
                'an SDA transition lasting at least the stated filter interval produced no filtered START/busy response'))
        else:
            observations.append((True, found.get('edge'),
                'busy rose after the filtered START signature for a transition sampled at the interval derived from floor(clk_cnt/4)'))

    if not observations:
        return (None, None, 'the qualified SDA filter-interval experiment was not exercised')
    for ok, edge, detail in observations:
        if not ok:
            return (False, edge, detail)
    if not saw_short or not saw_long:
        return (None, None, 'only one side of the stated filter-interval distinction was exercised')
    return (True, None, 'short SDA excursions were filtered and sufficiently sampled excursions produced the routed busy response using floor(clk_cnt/4); zero uses every enabled clock')

