def decide(trace):
    # No authoritative encoding table is provided for cmd, so do not compare
    # cmd against an invented numeric value.  An issued command is qualified by
    # a change on cmd while enabled and idle; the routed WRITE signature then
    # distinguishes this command from an unsupported or NOP command.
    from specflow.refmodel.temporal import after, TO_END, edges, worst

    def _out(row, name):
        return row.get('outputs', {}).get(name)

    def _inp(row, name):
        return row.get('inputs', {}).get(name)

    changes = edges(trace, 'cmd', 'change')
    windows = after(
        trace,
        lambda r: (
            r.get('edge') in changes
            and _inp(r, 'ena') == 1
            and _out(r, 'in_idle') == 1
        ),
        until=TO_END,
    )

    if not windows:
        return (None, None, 'no enabled idle command issuance was observed')

    verdicts = []
    for w in windows:
        rows = w.rows
        start = w.edge
        if len(rows) < 2:
            verdicts.append((None, start, 'the issued command window contains no later state'))
            continue

        din = _inp(rows[0], 'din')
        sda_ready = False
        scl_release = None
        scl_drive_low = None

        for i in range(1, len(rows)):
            prev = rows[i - 1]
            row = rows[i]

            # WRITE sets or releases SDA according to din before releasing SCL.
            if _out(row, 'sda_oen') == din:
                sda_ready = True

            if (
                _out(prev, 'scl_oen') == 0
                and _out(row, 'scl_oen') == 1
                and sda_ready
            ):
                scl_release = i
                break

        if scl_release is None:
            verdicts.append((False, start, 'cmd does not produce the WRITE signature: SDA is not prepared before SCL release'))
            continue

        for j in range(scl_release + 1, len(rows)):
            if (
                _out(rows[j - 1], 'scl_oen') == 1
                and _out(rows[j], 'scl_oen') == 0
            ):
                scl_drive_low = j
                break

        if scl_drive_low is None:
            verdicts.append((False, rows[scl_release]['edge'], 'cmd does not produce the WRITE signature: SCL is released but not subsequently driven low'))
        else:
            verdicts.append((True, rows[scl_drive_low]['edge'], 'cmd is recognized by the WRITE signature: SDA follows din, then SCL releases and returns low'))

    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row['outputs'].get(name)

    def changed_to(i, port, value):
        if i <= 0:
            return False
        return out(trace[i], port) == value and out(trace[i - 1], port) != value

    attempts = []
    for i, row in enumerate(trace):
        if (row['inputs'].get('ena') == 1
                and out(row, 'in_idle') == 1
                and out(row, 'clk_en_tick') == 1):
            attempts.append(i)

    if not attempts:
        return (None, None, 'no enabled idle acceptance point was observed')

    for start in attempts:
        din = trace[start]['inputs'].get('din')
        sda_seen = False
        scl_released = None

        for i in range(start + 1, len(trace)):
            if out(trace[i], 'sda_oen') == din:
                sda_seen = True

            if sda_seen and changed_to(i, 'scl_oen', 1):
                scl_released = i
                break

        if scl_released is None:
            continue

        for i in range(scl_released + 1, len(trace)):
            if changed_to(i, 'scl_oen', 0):
                return (
                    True,
                    trace[i]['edge'],
                    'WRITE command recognized by sda_oen following din, then '
                    'scl_oen releasing high and subsequently driving low'
                )

    return (
        None,
        None,
        'no WRITE output signature was observed; cmd encoding is unspecified '
        'because no authoritative cmd encoding table is provided'
    )

