def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def any_condition(conditions):
        def predicate(row):
            for condition in conditions:
                if all(
                    (out(row, name) if name in row.get('outputs', {}) else inp(row, name)) == value
                    for name, value in condition.items()
                ):
                    return True
            return False
        return predicate

    def arbitration_loss_trigger(row):
        # The declared line input is the available stimulus qualification for
        # the specification's observed-low condition; command encodings are
        # intentionally not inferred numerically.
        return (
            out(row, 'arbitration_checking') == 1
            and out(row, 'sda_oen') == 1
            and inp(row, 'sda_i') == 0
        )

    def unexpected_stop_trigger(row):
        return (
            out(row, 'active_command') == 1
            and out(row, 'stop_condition') == 1
            and out(row, 'in_stop_sequence') != 1
        )

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])
    closes = any_condition([
        {'al': 1},
        {'cmd_ack': 1},
    ])

    arbitration_windows = after(
        trace,
        arbitration_loss_trigger,
        until=closes,
        aborts=aborts,
    )
    stop_windows = after(
        trace,
        unexpected_stop_trigger,
        until=closes,
        aborts=aborts,
    )

    follows = True
    verdicts = []
    verdicts.extend(
        eventually(
            window,
            lambda row: out(row, 'al') == 1,
            strong=True,
            after_activation=follows,
        )
        for window in arbitration_windows
    )
    verdicts.extend(
        eventually(
            window,
            lambda row: out(row, 'al') == 1,
            strong=True,
            after_activation=follows,
        )
        for window in stop_windows
    )
    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def any_condition(conditions):
        def predicate(row):
            return any(
                all(
                    (out(row, name) if name in row.get('outputs', {}) else inp(row, name)) == value
                    for name, value in condition.items()
                )
                for condition in conditions
            )
        return predicate

    def active_command(row):
        return out(row, 'active_command') == 1

    def loss_condition(row):
        arbitration_loss = (
            out(row, 'arbitration_checking') == 1
            and out(row, 'sda_oen') == 1
            and inp(row, 'sda_i') == 0
        )
        unexpected_stop = (
            out(row, 'stop_condition') == 1
            and out(row, 'active_command') == 1
            and out(row, 'in_stop_sequence') != 1
        )
        return arbitration_loss or unexpected_stop

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])
    closes = any_condition([
        {'al': 1},
        {'cmd_ack': 1},
    ])

    windows = after(
        trace,
        active_command,
        until=closes,
        aborts=aborts,
    )

    verdicts = []
    for window in windows:
        rows = window.rows
        for event_pos, row in enumerate(rows):
            if not loss_condition(row):
                continue

            for response_pos in range(event_pos + 1, len(rows)):
                previous = out(rows[response_pos - 1], 'al')
                current = out(rows[response_pos], 'al')
                if previous != 1 and current == 1:
                    verdicts.append((
                        True,
                        rows[response_pos].get('edge'),
                        'al asserted after the arbitration-loss condition'
                    ))
                    break
            else:
                verdicts.append((
                    False,
                    row.get('edge'),
                    'al was not asserted after the arbitration-loss condition'
                ))
            break

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def is_reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def loss_event(row):
        arbitration_loss = (
            out(row, 'arbitration_checking') == 1
            and out(row, 'sda_oen') == 1
            and inp(row, 'sda_i') == 0
        )
        unexpected_stop = (
            out(row, 'active_command') == 1
            and out(row, 'stop_condition') == 1
            and out(row, 'in_stop_sequence') != 1
        )
        return arbitration_loss or unexpected_stop

    windows = after(
        trace,
        lambda r: out(r, 'active_command') == 1,
        until=lambda r: out(r, 'al') == 1 or out(r, 'cmd_ack') == 1,
        aborts=is_reset,
    )

    verdicts = []
    for window in windows:
        rows = window.rows
        for event_pos, row in enumerate(rows):
            if not loss_event(row):
                continue

            response = None
            for response_row in rows[event_pos:]:
                if out(response_row, 'al') == 1:
                    response = response_row
                    break

            if response is not None:
                verdicts.append((
                    True,
                    response.get('edge'),
                    'al asserted after an arbitration-loss condition'
                ))
            elif any(is_reset(r) for r in rows[event_pos + 1:]):
                verdicts.append((
                    None,
                    row.get('edge'),
                    'arbitration-loss attempt was aborted by reset'
                ))
            else:
                verdicts.append((
                    False,
                    row.get('edge'),
                    'al was not asserted after an arbitration-loss condition'
                ))
            break

    return worst(verdicts)

