def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    # A command phase is a declared design situation.  Inputs qualify it;
    # they do not open the window by themselves.
    phase_rises = set()
    for probe in ("in_start_sequence", "in_stop_sequence", "in_write_sequence"):
        phase_rises.update(edges(trace, probe, "rise"))

    def applies(row):
        return (
            row.get("edge") in phase_rises
            and row.get("inputs", {}).get("ena") == 1
            and row.get("inputs", {}).get("cmd") in (1, 2, 4)
        )

    windows = after(trace, applies, until=TO_END)
    if not windows:
        return (None, None, "no enabled supported command entered an observed SDA-driving phase")

    low_entries = set(edges(trace, "sda_oen", "fall"))
    verdicts = [
        eventually(
            w,
            lambda r: r.get("edge") in low_entries
            and r.get("outputs", {}).get("sda_oen") == 0,
            after_activation=True,
            strong=True,
        )
        for w in windows
    ]
    return worst(verdicts)

