        throughout(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 0,
            after_activation=True
        )
        for window in wait_windows
    ]

    rising_edges = edges(trace, 'scl_i', 'rise')
    release_edges = set()
    for window in wait_windows:
        for row in window.rows:
            if row.get('edge') in rising_edges:
                release_edges.add(row.get('edge'))

    release_windows = after(
        trace,
        lambda row: row.get('edge') in release_edges,
        until=TO_END
    ) if release_edges else []

    resume_verdicts = [
        eventually(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
