def decide(trace):
    activations = []
    for i, row in enumerate(trace):
        out = row.get('outputs', {})
        inp = row.get('inputs', {})
        event = out.get('scl_sync_event') == 1
        prior_event = (i > 0 and
                       trace[i - 1].get('outputs', {}).get('scl_sync_event') == 1)
        if event and not prior_event and inp.get('ena') == 1 and inp.get('scl_i') == 0:
            activations.append(i)

    if not activations:
        return (None, None, 'scl_sync_event never occurred while ena was high and scl_i was low')

    for i in activations:
        event_row = trace[i]
        event_edge = event_row['edge']
        event_oen = event_row.get('outputs', {}).get('scl_oen')
        if event_oen != 1:
            return (False, event_edge,
                    'scl_sync_event occurred but scl_oen was not released high')

        j = i
        while j < len(trace) and trace[j].get('inputs', {}).get('scl_i') == 0:
            if trace[j].get('outputs', {}).get('scl_oen') != 1:
                return (False, trace[j]['edge'],
                        'scl_oen changed from released high while the shared SCL remained low')
            j += 1

        if j == len(trace):
            return (None, None,
                    'scl_sync_event occurred and scl_oen remained released, but the shared SCL did not return high in the trace')

        prev_oen = trace[j - 1].get('outputs', {}).get('scl_oen')
        transition = None
        for k in range(j, len(trace)):
            oen = trace[k].get('outputs', {}).get('scl_oen')
            if prev_oen == 1 and oen != 1:
                transition = k
                break
            prev_oen = oen

        if transition is None:
            return (None, None,
                    'scl_oen stayed released while scl_i was low, but no subsequent SCL control transition was observed')

    return (True, trace[activations[0]]['edge'],
            'scl_oen remained released until scl_i returned high, then the next SCL control transition occurred')

