def decide(trace):
    from specflow.refmodel.temporal import edges

    if not trace:
        return (None, None, 'no states were observed for raw-input synchronization')

    scl_changes = edges(trace, 'scl_i', 'change')
    sda_changes = edges(trace, 'sda_i', 'change')
    change_edges = scl_changes | sda_changes
    immediate_failure = None
    positive_evidence = None

    # A raw transition must not cause an immediate dout change.  The
    # comparison is against the preceding distinct state, not a fixed clock
    # count; this detects a bypass of the synchronization path without
    # asserting any implementation-specific latency.
    for i, row in enumerate(trace):
        if row['edge'] not in change_edges or row['inputs'].get('ena') != 1:
            continue
        if i > 0:
            before = trace[i - 1]['outputs'].get('dout')
            now = row['outputs'].get('dout')
            if before is not None and now is not None and now != before:
                immediate_failure = (row['edge'], 'raw scl_i or sda_i transition changed dout immediately')
                break

    if immediate_failure is not None:
        return (False, immediate_failure[0], immediate_failure[1])

    # Look for the route's positive case: a raw SDA value remains stable
    # through a qualifying filtered SCL rising edge while enabled, and dout
    # later reaches that value.  No number of intervening states is imposed.
    for i, row in enumerate(trace):
        if row['edge'] not in sda_changes or row['inputs'].get('ena') != 1:
            continue
        target = row['inputs'].get('sda_i')
        old_dout = row['outputs'].get('dout')
        rise_i = None
        for j in range(i + 1, len(trace)):
            if trace[j]['inputs'].get('sda_i') != target:
                break
            if (trace[j]['inputs'].get('ena') == 1 and
                    trace[j]['outputs'].get('filtered_scl_rise') == 1):
                rise_i = j
                break
        if rise_i is None:
            continue
        for k in range(rise_i + 1, len(trace)):
            if trace[k]['inputs'].get('sda_i') != target:
                break
            if trace[k]['outputs'].get('dout') == target:
                if old_dout != target:
                    positive_evidence = trace[k]['edge']
                break
        if positive_evidence is not None:
            break

    if positive_evidence is not None:
        return (True, positive_evidence, 'dout reflected stable raw sda_i after a filtered SCL rising edge; raw transitions did not immediately change dout')
    return (None, None, 'the route through dout did not provide both non-immediate and post-synchronization evidence')

