def decide(trace):
    attempts = []

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        # A raw SDA transition while SCL is high is the route's
        # START/STOP-shaped activation.  Inputs qualify the situation only.
        if inp(row, 'ena') != 1 or inp(row, 'scl_i') != 1:
            continue
        if inp(prev, 'scl_i') != 1:
            continue
        if inp(prev, 'sda_i') == inp(row, 'sda_i'):
            continue

        start_edge = row['edge']
        baseline_busy = out(prev, 'busy')
        sample_seen = False
        saw_busy_change_after_sample = False
        aborted = False

        for j in range(i, len(trace)):
            current = trace[j]

            if (inp(current, 'nReset') == 0 or
                    inp(current, 'rst') == 1):
                aborted = True
                break

            busy_changed = False
            if j > 0:
                busy_changed = out(current, 'busy') != out(trace[j - 1], 'busy')

            # A response on the activation state, or before the first
            # sampling opportunity, bypasses the filter cadence.
            if busy_changed and not sample_seen:
                attempts.append((False, current['edge'],
                                 'busy changed before filter sampling admitted the raw SDA transition'))
                break

            if out(current, 'filter_sample_event') == 1:
                sample_seen = True

            if sample_seen and busy_changed:
                saw_busy_change_after_sample = True
                attempts.append((True, current['edge'],
                                 'busy changed only after a filter sampling event; raw transition edge was ' + str(start_edge)))
                break
        else:
            if not aborted and sample_seen and not saw_busy_change_after_sample:
                attempts.append((None, None,
                                 'filter sampling occurred but no routed busy response was observed'))

        if aborted:
            attempts.append((None, None,
                             'raw transition attempt was aborted by reset before the filter response could be observed'))

    if not attempts:
        return (None, None, 'no enabled START- or STOP-shaped raw SDA transition while SCL was high')

    for ok, edge, detail in attempts:
        if ok is False:
            return (False, edge, detail)

    for ok, edge, detail in attempts:
        if ok is True:
            return (True, edge, detail)

    return (None, None, 'the raw transition was not shown to be admitted and routed to busy')

