def decide(trace):
    from specflow.refmodel.temporal import after, edges, throughout, stable, worst

    sda_falls = edges(trace, "sda_i", "fall")
    sda_rises = edges(trace, "sda_i", "rise")

    def glitch_start(row):
        return (row["edge"] in sda_falls
                and row["inputs"].get("scl_i") == 1
                and row["outputs"].get("busy") == 0)

    windows = after(
        trace,
        glitch_start,
        until=lambda row: row["edge"] in sda_rises
    )

    short_glitches = []
    for window in windows:
        rows = window.rows
        if not rows or not window.closed:
            continue
        if not all(row["inputs"].get("scl_i") == 1 for row in rows):
            continue
        sample_count = sum(
            1 for row in rows
            if row["inputs"].get("sda_i") == 0
            and row["outputs"].get("filter_sample_event") == 1
        )
        if sample_count < 3:
            short_glitches.append(window)

    busy_rises = edges(trace, "busy", "rise")
    start_rows = [
        i for i, row in enumerate(trace)
        if row["outputs"].get("start_condition") == 1
    ]
    ordinary_busy_evidence = any(
        row["edge"] in busy_rises
        and any(start_i <= i for start_i in start_rows)
        for i, row in enumerate(trace)
    )

    if not short_glitches:
        return (None, None, "no closed SDA-low glitch narrower than the three-sample filter window occurred")
    if not ordinary_busy_evidence:
        return (None, None, "busy never showed its ordinary rise after a genuine START, so the routed observation is not discriminating")

    return worst([
        throughout(window, lambda row: row["outputs"].get("busy") == 0,
                   after_activation=False)
        for window in short_glitches
    ])

