        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def _any(alternatives):
        predicates = [_holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    start = lambda row: (
        _holds({'ena': 1, 'scl_i': 1, 'sda_i': 0})(row)
        and row['outputs'].get('start_condition') == 1
    )
    stop = lambda row: row['outputs'].get('stop_condition') == 1
    reset = _any([{'nReset': 0}, {'rst': 1}])

    start_windows = after(
        trace,
        start,
        until=stop,
        aborts=reset,
