def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                actual = row['outputs'].get(port, row['inputs'].get(port))
                if actual != value:
                    return False
            return True
        return predicate

    # A non-STOP active command is identified by its declared command-phase
    # probes, rather than by an unstated numeric encoding of cmd.
    phase_alternatives = [
        {'active_command': 1, 'stop_condition': 1, 'in_start_sequence': 1, 'al': 0},
        {'active_command': 1, 'stop_condition': 1, 'in_read_sequence': 1, 'al': 0},
        {'active_command': 1, 'stop_condition': 1, 'in_write_sequence': 1, 'al': 0}
    ]
    raw_alternatives = [
        {'active_command': 1, 'stop_condition': 1, 'in_start_sequence': 1},
        {'active_command': 1, 'stop_condition': 1, 'in_read_sequence': 1},
        {'active_command': 1, 'stop_condition': 1, 'in_write_sequence': 1}
    ]

    trigger = lambda row: any(holds(cond)(row) for cond in phase_alternatives)
    raw_trigger = lambda row: any(holds(cond)(row) for cond in raw_alternatives)

    raw_rows = [row for row in trace if raw_trigger(row)]
    if raw_rows and not any(trigger(row) for row in trace):
        return (None, raw_rows[0]['edge'],
                'unexpected STOP occurred while al was already high; this trace cannot show a new assertion caused by the STOP')

    windows = after(trace, trigger,
                    until=lambda row: row['outputs'].get('al') == 1)
    return worst([
        eventually(window,
                   lambda row: row['outputs'].get('al') == 1,
                   strong=True,
                   after_activation=True)
        for window in windows
    ])

