def decide(trace):
    state_ports = (
        'in_idle',
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def state(row):
        outputs = row.get('outputs', {})
        return tuple(outputs.get(port, 0) for port in state_ports)

    transitions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if state(previous) == state(current):
            continue

        # Reset may change the FSM state without a timing-enable tick.
        prev_inputs = previous.get('inputs', {})
        curr_inputs = current.get('inputs', {})
        if (prev_inputs.get('nReset') == 0 or curr_inputs.get('nReset') == 0 or
                prev_inputs.get('rst') == 1 or curr_inputs.get('rst') == 1):
            continue

        transitions.append((i, current))
        outputs = current.get('outputs', {})
        if outputs.get('clk_en_tick', 0) != 1:
            return (
                False,
                current.get('edge'),
                'FSM state advanced without clk_en_tick asserted'
            )

    if not transitions:
        return (None, None, 'no non-reset FSM advancement was observed')

    return (
        True,
        transitions[-1][1].get('edge'),
        'every observed non-reset FSM state advancement occurred with clk_en_tick asserted'
    )

