def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def probe(name):
        return lambda r: r['outputs'].get(name) == 1

    def out(**values):
        return lambda r: all(r['outputs'].get(k) == v for k, v in values.items())

    def write_phase(sda_value, scl_value):
        return lambda r: (
            r['outputs'].get('sda_oen') == sda_value and
            r['outputs'].get('scl_oen') == scl_value and
            r['inputs'].get('din') == (1 if sda_value == 1 else 0)
        )

    def any_abort(r):
        return (
            r['outputs'].get('al') == 1 or
            r['inputs'].get('nReset') == 0 or
            r['inputs'].get('rst') == 1
        )

    def windows_for(name):
        return after(
            trace,
            probe(name),
            until=out(cmd_ack=1),
            aborts=any_abort
        )

    verdicts = []

    # START: SDA low while SCL is released, then both lines driven low.
    for w in windows_for('in_start_sequence'):
        verdicts.append(sequence(
            w,
            out(scl_oen=1, sda_oen=0),
            out(scl_oen=0, sda_oen=0),
            strong=True,
            after_activation=True
        ))

    # STOP: SDA low, then SCL released, then SDA released while SCL is high.
    for w in windows_for('in_stop_sequence'):
        verdicts.append(sequence(
            w,
            out(scl_oen=1, sda_oen=0),
            out(scl_oen=1, sda_oen=1),
            strong=True,
            after_activation=True
        ))

    # READ: SDA released while SCL is released, then SCL driven low.
    for w in windows_for('in_read_sequence'):
        verdicts.append(sequence(
            w,
            out(scl_oen=1, sda_oen=1),
            out(scl_oen=0, sda_oen=1),
            strong=True,
            after_activation=True
        ))

    # WRITE: SDA follows din during the released-SCL phase, then SCL is driven low.
    for w in windows_for('in_write_sequence'):
        verdicts.append(sequence(
            w,
            write_phase(0, 1),
            write_phase(0, 0),
            strong=True,
            after_activation=True
        ))
        verdicts.append(sequence(
            w,
            write_phase(1, 1),
            write_phase(1, 0),
            strong=True,
            after_activation=True
        ))

    return worst(verdicts)

