from specflow.refmodel.temporal import TO_END, after, eventually, pulse, worst


def _condition(values):
    def holds(row):
        for port, value in values.items():
            actual = row['outputs'].get(port, row['inputs'].get(port))
            if isinstance(value, list):
                if actual not in value:
                    return False
            elif actual != value:
                return False
        return True
    return holds


def _any_condition(alternatives):
    predicates = [_condition(item) for item in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    activation = _condition({
        'cmd': [1, 2, 4, 8],
        'ena': 1,
    })
    aborts = _any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        activation,
        until=_condition({'cmd_ack': 1}),
        aborts=aborts,
    )
    follows = True

    pulse_results = [
        pulse(
            window,
            'cmd_ack',
            width=1,
            active=1,
            after_activation=follows,
        )
        for window in windows
    ]
    idle_results = [
        eventually(
            window,
            lambda row: (
                row['outputs'].get('cmd_ack') == 1
                and row['outputs'].get('in_idle') == 1
            ),
            strong=True,
            after_activation=follows,
        )
        for window in windows
    ]

    return worst(pulse_results + idle_results)

