def decide(trace):
    if not trace:
        return (None, None, 'reset release and sampled bus activity were not observed')

    # Locate completion of either reset initialization, treating either reset
    # input as reset-active.  Inputs qualify the activation; they are not the
    # expected behavior.
    reset_was_active = False
    reset_release = None
    for i, row in enumerate(trace):
        ins = row.get('inputs', {})
        active = ins.get('nReset') == 0 or ins.get('rst') == 1
        if active:
            reset_was_active = True
        elif reset_was_active:
            reset_release = i
            reset_was_active = False

    if reset_release is None:
        return (None, None, 'reset was not observed being released')

    def probe_rises(name):
        rises = []
        for i in range(reset_release, len(trace)):
            row = trace[i]
            if row.get('inputs', {}).get('ena') != 1:
                continue
            now = row.get('outputs', {}).get(name) == 1
            before = False if i == reset_release else trace[i - 1].get('outputs', {}).get(name) == 1
            if now and not before:
                rises.append(i)
        return rises

    starts = probe_rises('start_condition')
    stops = probe_rises('stop_condition')

    if not starts or not stops:
        return (None, None, 'only one side of the routed sampling signature was observed')

    for start_i in starts:
        later_stops = [i for i in stops if i > start_i]
        if not later_stops:
            continue
        stop_i = later_stops[0]

        busy_after_start = next(
            (i for i in range(start_i, stop_i + 1)
             if trace[i].get('outputs', {}).get('busy') == 1),
            None)
        if busy_after_start is None:
            return (False, trace[start_i]['edge'],
                    'busy did not set after the valid sampled START condition')

        busy_after_stop = next(
            (i for i in range(stop_i, len(trace))
             if trace[i].get('outputs', {}).get('busy') == 0),
            None)
        if busy_after_stop is None:
            return (False, trace[stop_i]['edge'],
                    'busy did not clear after the valid sampled STOP condition')

        return (True, trace[busy_after_stop]['edge'],
                'after reset release, busy set on the sampled START and cleared on the later sampled STOP')

    return (None, None, 'START and STOP observations were not seen in the required order')

