def decide(trace):
    rises = []
    for i, row in enumerate(trace):
        out = row.get('outputs', {})
        if out.get('filtered_scl_rise') == 1:
            rises.append(i)

    if not rises:
        return (None, None, 'filtered SCL never rose; no routed observation occurred')

    checked = []
    for i in rises:
        row = trace[i]
        out = row.get('outputs', {})
        dout = out.get('dout')
        sda = row.get('inputs', {}).get('sda_i')
        if dout is None or sda is None:
            continue

        prev_sda = trace[i - 1].get('inputs', {}).get('sda_i') if i > 0 else None
        prev_dout = trace[i - 1].get('outputs', {}).get('dout') if i > 0 else None

        # A raw transition at the sampling observation is the routed
        # late-transition case.  The captured path must retain its prior value.
        if (i > 0 and prev_sda is not None and prev_dout is not None
                and sda != prev_sda and sda != prev_dout):
            checked.append((i, 'late'))
            if dout != prev_dout:
                return (False, row.get('edge'),
                        'at filtered SCL rise, a late raw sda_i transition replaced the previously captured dout value')
            continue

        # Establish that raw SDA was stable for the stated two-stage capture
        # and three-sample filter before using the positive routed observation.
        samples = 0
        stable_edges = 0
        j = i
        while j >= 0:
            r = trace[j]
            ri = r.get('inputs', {}).get('sda_i')
            if ri != sda:
                break
            stable_edges += r.get('held', 0)
            if r.get('outputs', {}).get('filter_sample_event') == 1:
                samples += 1
            j -= 1

        if samples >= 3 and stable_edges >= 2:
            checked.append((i, 'stable'))
            if dout != sda:
                return (False, row.get('edge'),
                        'dout did not capture the stable sda_i value at the filtered SCL rising edge')

    if not checked:
        return (None, None,
                'filtered SCL rose, but no stable-three-sample or discriminating late-transition observation occurred')

    return (True, trace[checked[-1][0]].get('edge'),
            'dout matched the stable filtered observation and preserved its prior value for any qualifying late raw transition')

