    events = []
    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if (inputs.get('ena') == 1 and inputs.get('nReset') == 1
                and inputs.get('rst') == 0
                and outputs.get('filter_sample_event') == 1):
            # Keep only the first row of a held event indication.
            if not events or events[-1][0] != i - 1:
                events.append((i, inputs.get('clk_cnt'), row.get('edge')))

    checks = []
    for pos in range(1, len(events)):
        first_i, first_cnt, _ = events[pos - 1]
        second_i, second_cnt, second_edge = events[pos]
        if first_cnt is None or second_cnt != first_cnt:
            continue

        enabled_edges = 0
        comparable = True
        for row in trace[first_i:second_i]:
            inp = row.get('inputs', {})
            if inp.get('ena') != 1 or inp.get('nReset') != 1 or inp.get('rst') != 0:
                comparable = False
                break
            if inp.get('clk_cnt') != first_cnt:
                comparable = False
                break
            enabled_edges += row.get('held', 1)

        if not comparable:
            continue

        stated_interval = first_cnt >> 2
        expected_interval = max(1, stated_interval)
        checks.append((enabled_edges, expected_interval, second_edge, first_cnt))

    if not checks:
        return (None, None, 'no two comparable filter sampling events occurred')

    for observed, expected, edge, count in checks:
        if observed != expected:
            return (
                False,
                edge,
                f"filter sampling interval was {observed} enabled edges for clk_cnt={count}, "
                f"expected floor(clk_cnt / 4)={expected}; requirement says "
                "'A filter counter, filter_cnt, derives its sampling interval from clk_cnt >> 2.'"
            )

    return (
        True,
        checks[-1][2],
        "filter sampling events followed the interval derived from clk_cnt >> 2 "
        "('A filter counter, filter_cnt, derives its sampling interval from clk_cnt >> 2.')"
    )

