def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return out(row, name)

    qualified_seen = False
    ordinary_seen = False

    for i, row in enumerate(trace):
        if inp(row, 'ena') != 1:
            continue

        # The normalized activation opens on the filter_sample_event probe.
        # Treat it as an event, not as a held level.
        if probe(row, 'filter_sample_event') != 1:
            continue
        if i > 0 and probe(trace[i - 1], 'filter_sample_event') == 1:
            continue

        is_start = probe(row, 'start_condition') == 1
        is_stop = probe(row, 'stop_condition') == 1

        if is_start or is_stop:
            qualified_seen = True
            expected_busy = 1 if is_start else 0
            if out(row, 'busy') != expected_busy:
                kind = 'START' if is_start else 'STOP'
                return (
                    False,
                    row.get('edge'),
                    f"at an enabled filter-sample boundary with a majority-qualified {kind} transition, busy was {out(row, 'busy')!r}; expected {expected_busy}"
                )
            continue

        # The route's otherwise case: a non-qualified sample must not change
        # the status observable through REQ-0069.
        if i == 0:
            continue
        previous = trace[i - 1]
        if out(previous, 'busy') is None or out(row, 'busy') is None:
            continue
        ordinary_seen = True
        if out(row, 'busy') != out(previous, 'busy'):
            return (
                False,
                row.get('edge'),
                'busy changed at an enabled filter-sample boundary without a majority-qualified START or STOP transition'
            )

    if not qualified_seen or not ordinary_seen:
        missing = []
        if not qualified_seen:
            missing.append('a majority-qualified START or STOP case')
        if not ordinary_seen:
            missing.append('a non-qualified majority-filter case')
        return (
            None,
            None,
            'activation occurred insufficiently to distinguish both sides of the majority-filter signature; missing '
            + ' and '.join(missing)
        )

    return (
        True,
        None,
        'enabled filter-sample boundaries showed the qualified and non-qualified busy signatures required by majority filtering'
    )

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def probe(row, name):
        return out(row, name)

    samples = [
        i for i, row in enumerate(trace)
        if row.get('inputs', {}).get('ena') == 1
        and probe(row, 'filter_sample_event') == 1
    ]
    if not samples:
        return (None, None, 'filter_sample_event never occurred while ena was high')

    qualified = False
    ordinary = False

    for i in samples:
        row = trace[i]
        start = probe(row, 'start_condition') == 1
        stop = probe(row, 'stop_condition') == 1

        if start or stop:
            qualified = True
            expected = 1 if start else 0
            if out(row, 'busy') != expected:
                kind = 'START' if start else 'STOP'
                return (
                    False,
                    row.get('edge'),
                    f'after a majority-qualified {kind} filter transition, busy was {out(row, "busy")!r}; expected {expected}'
                )
        else:
            ordinary = True
            if i > 0 and out(trace[i - 1], 'busy') is not None:
                if out(row, 'busy') != out(trace[i - 1], 'busy'):
                    return (
                        False,
                        row.get('edge'),
                        'busy changed at a filter-sample boundary without a majority-qualified START or STOP transition'
                    )

    if not qualified and not ordinary:
        return (None, None, 'filter-sample activation occurred but produced no observable busy case')

    return (
        True,
        None,
        'enabled filter-sample states produced the busy signature required for majority-filtered transitions'
    )

