def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def probe(row, name):
        return row.get('outputs', {}).get(name, False)

    def raw_line_changed(i):
        if i == 0:
            return False
        previous = trace[i - 1].get('inputs', {})
        current = trace[i].get('inputs', {})
        return (previous.get('scl_i') != current.get('scl_i') or
                previous.get('sda_i') != current.get('sda_i'))

    verdicts = []
    for condition, desired, label in (
        ('start_condition', 1, 'filtered START'),
        ('stop_condition', 0, 'filtered STOP'),
    ):
        windows = after(
            trace,
            lambda row, condition=condition: probe(row, condition),
            until=TO_END,
        )
        verdicts.extend(
            eventually(
                window,
                lambda row, desired=desired: row.get('outputs', {}).get('busy') == desired,
                after_activation=False,
                strong=True,
            )
            for window in windows
        )

    observed_condition = any(
        probe(row, 'start_condition') or probe(row, 'stop_condition')
        for row in trace
    )

    for i, row in enumerate(trace):
        if (raw_line_changed(i) and
                not probe(row, 'start_condition') and
                not probe(row, 'stop_condition')):
            if i > 0:
                before = trace[i - 1].get('outputs', {}).get('busy')
                current = row.get('outputs', {}).get('busy')
                if current != before:
                    return (
                        False,
                        row.get('edge'),
                        'raw SCL/SDA changed without a filtered START or STOP, '
                        'but busy changed'
                    )

    if not observed_condition:
        return (None, None, 'no filtered START or STOP condition occurred')
    return worst(verdicts)

