def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    start_events = edges(trace, "start_condition", "rise")
    stop_events = edges(trace, "stop_condition", "rise")
    busy_rises = edges(trace, "busy", "rise")
    busy_falls = edges(trace, "busy", "fall")
    follows = False

    windows = []
    for event_edges, busy_edges, name, value in (
        (start_events, busy_rises, "START", 1),
        (stop_events, busy_falls, "STOP", 0),
    ):
        if event_edges:
            event_windows = after(
                trace,
                lambda row, es=event_edges: row["edge"] in es,
                until=TO_END,
            )
            windows.extend(
                (window, busy_edges, name, value)
                for window in event_windows
            )

    if not windows:
        return (None, None, "no filtered START or STOP transition occurred")

    verdicts = []
    for window, busy_edges, name, value in windows:
        verdicts.append(
            eventually(
                window,
                lambda row, es=busy_edges, expected=value: (
                    row["edge"] in es
                    and row["outputs"].get("busy") == expected
                ),
                strong=False,
                after_activation=follows,
            )
        )

    return worst(verdicts)

