def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        return out(row, '__never__') is not None or (
            row.get('inputs', {}).get('nReset') == 0 or
            row.get('inputs', {}).get('rst') == 1
        )

    starts = []
    stops = []
    for i, row in enumerate(trace):
        prev = trace[i - 1] if i else None
        start_now = bool(out(row, 'start_condition'))
        stop_now = bool(out(row, 'stop_condition'))
        start_before = bool(out(prev, 'start_condition')) if prev is not None else False
        stop_before = bool(out(prev, 'stop_condition')) if prev is not None else False
        if start_now and not start_before:
            starts.append((i, row, prev))
        if stop_now and not stop_before:
            stops.append((i, row, prev))

    if not starts or not stops:
        return (None, None,
                'both filtered START and STOP comparison events are required; '
                'the trace exercised only one event case')

    for i, row, prev in starts:
        if out(row, 'busy') != 1:
            return (False, row.get('edge'),
                    'filtered SDA high-to-low transition while SCL is high did not make busy high')
        if prev is None:
            return (None, row.get('edge'),
                    'START comparison event lacks a preceding state to establish the busy change')
        if not reset_active(row) and not reset_active(prev) and out(prev, 'busy') != 0:
            return (False, row.get('edge'),
                    'busy was not low before the filtered START comparison event')

    for i, row, prev in stops:
        if out(row, 'busy') != 0:
            return (False, row.get('edge'),
                    'filtered SDA low-to-high transition while SCL is high did not make busy low')
        if prev is None:
            return (None, row.get('edge'),
                    'STOP comparison event lacks a preceding state to establish the busy change')
        if not reset_active(row) and not reset_active(prev) and out(prev, 'busy') != 1:
            return (False, row.get('edge'),
                    'busy was not high before the filtered STOP comparison event')

    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if reset_active(row) or reset_active(prev):
            continue
        changed = out(row, 'busy') != out(prev, 'busy')
        event = bool(out(row, 'start_condition')) or bool(out(row, 'stop_condition'))
        if changed and not event:
            return (False, row.get('edge'),
                    'busy changed without a filtered START or STOP comparison event')

    return (True, stops[-1][1].get('edge'),
            'filtered START and STOP comparison events produced the required busy transitions')

