def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def holds(cond):
        def predicate(row):
            values = {}
            values.update(row.get('inputs', {}))
            values.update(row.get('outputs', {}))
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    # Use the declared wait-state probe and the port-level low-SCL signature;
    # no unstated command encoding is needed.
    waiting = lambda row: (
        holds({'slave_wait': 1, 'active_command': 1, 'ena': 1, 'scl_i': 0})(row)
    )
    wait_windows = after(
        trace,
        waiting,
        until=holds({'slave_wait': 0}),
        aborts=aborts,
    )

    paused = [
        throughout(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 0,
            after_activation=True,
        )
        for window in wait_windows
    ]

    # The routed observation must also show the postponed normal completion;
    # otherwise a design that never advances would pass the low-level check.
    wait_falls = edges(trace, 'slave_wait', 'fall')
    released_windows = after(
        trace,
        lambda row: row.get('edge') in wait_falls,
        until=TO_END,
        aborts=aborts,
    )
    postponed = [
        eventually(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
            strong=False,
        )
        for window in released_windows
    ]

    return worst(paused + postponed)

