def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def valid_row(row):
        return (inp(row, 'ena') == 1 and
                inp(row, 'nReset') == 1 and
                inp(row, 'rst') == 0 and
                out(row, 'al') == 0 and
                out(row, 'slave_wait') == 0 and
                out(row, 'scl_sync_event') == 0)

    # The active_command probe is the declared signature that a supported
    # command has been accepted; no unstated cmd encoding is used.
    starts = []
    for i, row in enumerate(trace):
        active = out(row, 'active_command') == 1
        prior = out(trace[i - 1], 'active_command') == 1 if i else False
        if active and not prior and valid_row(row):
            starts.append(i)

    transactions = []
    for i in starts:
        aborted = False
        ack_index = None
        for j in range(i, len(trace)):
            if not valid_row(trace[j]):
                aborted = True
                break
            if out(trace[j], 'cmd_ack') == 1:
                ack_index = j
                break
        if aborted or ack_index is None:
            continue
        elapsed_edges = sum(max(1, int(trace[k].get('held', 1)))
                            for k in range(i, ack_index + 1))
        transactions.append({
            'index': i,
            'cmd': inp(trace[i], 'cmd'),
            'din': inp(trace[i], 'din'),
            'scl_i': inp(trace[i], 'scl_i'),
            'sda_i': inp(trace[i], 'sda_i'),
            'clk_cnt': inp(trace[i], 'clk_cnt'),
            'elapsed': elapsed_edges,
            'ack_edge': trace[ack_index].get('edge')
        })

    comparisons = []
    for a in range(len(transactions)):
        for b in range(a + 1, len(transactions)):
            x = transactions[a]
            y = transactions[b]
            same_context = (x['cmd'] == y['cmd'] and
                            x['din'] == y['din'] and
                            x['scl_i'] == y['scl_i'] and
                            x['sda_i'] == y['sda_i'])
            if not same_context or x['clk_cnt'] == y['clk_cnt']:
                continue
            low, high = (x, y) if x['clk_cnt'] < y['clk_cnt'] else (y, x)
            comparisons.append((low, high))
            if high['elapsed'] <= low['elapsed']:
                return (False, high['ack_edge'],
                        'with the same opaque command context, increasing clk_cnt did not delay cmd_ack; '
                        'the required counter timing relationship was not observed')

    if not starts:
        return (None, None, 'no accepted supported command was observed')
    if not transactions:
        return (None, None, 'accepted command attempts were incomplete or aborted before cmd_ack')
    if not comparisons:
        return (None, None,
                'no two non-aborted matching command transactions with different clk_cnt values were observed; '
                'the clk_cnt-dependent timing relationship cannot be decided')
    return (True, None,
            'for every comparable non-aborted command pair, the larger clk_cnt delayed cmd_ack; '
            'no exact latency was required')

