def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def qualified(row):
        return (
            inp(row, 'ena') == 1 and
            inp(row, 'rst') == 0 and
            inp(row, 'nReset') == 1 and
            out(row, 'al') == 0 and
            out(row, 'cmd_ack') == 0
        )

    saw_window = False
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]

        # The route observes the enabled WRITE stable-high phase before
        # command completion.  The probe is declared and is the licensed
        # signature of that situation.
        in_route = (
            out(previous, 'write_stable_high_phase') == 1 and
            qualified(previous)
        )
        if in_route:
            saw_window = True

        # Reaching the next phase is observed as the released SCL enable
        # changing from 1 to 0.  It is legal only when clk_en_tick is asserted
        # at the state in which that change becomes visible.
        advanced = (
            out(previous, 'scl_oen') == 1 and
            out(current, 'scl_oen') == 0
        )
        if advanced and in_route and out(current, 'clk_en_tick') != 1:
            return (
                False,
                current.get('edge'),
                'scl_oen advanced from 1 to 0 during the WRITE stable-high phase '
                'without clk_en_tick being asserted'
            )

    if not saw_window:
        return (None, None, 'the enabled WRITE stable-high phase was not observed')

    return (True, None, 'every observed stable-high phase advance of scl_oen was enabled by clk_en_tick')

