def decide(trace):
    def active_disabled(row):
        return (row['inputs'].get('ena') == 0 and
                row['outputs'].get('active_command') == 1)

    def closes(row):
        return (row['inputs'].get('ena') != 0 or
                row['outputs'].get('active_command') != 1 or
                row['outputs'].get('cmd_ack') == 1)

    def enabled_progress_witness():
        for i in range(1, len(trace)):
            prev = trace[i - 1]
            cur = trace[i]
            if (prev['inputs'].get('ena') == 1 and
                    cur['inputs'].get('ena') == 1 and
                    prev['outputs'].get('active_command') == 1 and
                    cur['outputs'].get('active_command') == 1 and
                    prev['outputs'].get('scl_oen') != cur['outputs'].get('scl_oen')):
                return True
        return False

    from specflow.refmodel.temporal import after, stable, worst

    windows = after(trace, active_disabled, until=closes)
    verdict = worst([
        stable(w, 'scl_oen', after_activation=False)
        for w in windows
    ])

    if verdict[0] is False:
        return verdict
    if verdict[0] is None:
        return verdict
    if not enabled_progress_witness():
        return (None, None,
                'disabled active-command window was observed, but no enabled '
                'scl_oen phase transition showed the routed normal-progress case')
    return (True, verdict[1],
            'scl_oen remained at its current FSM phase while ena was low '
            'during an active command')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def disabled_active(row):
        return (row.get('inputs', {}).get('ena') == 0 and
                out(row, 'active_command') == 1 and
                out(row, 'cmd_ack') != 1)

    disabled_rows = [r for r in trace if disabled_active(r)]
    if not disabled_rows:
        return (None, None,
                'no active supported command was observed while ena was low')

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        cur = trace[i]
        if (disabled_active(prev) and disabled_active(cur) and
                out(prev, 'scl_oen') != out(cur, 'scl_oen')):
            return (False, cur.get('edge'),
                    'scl_oen changed during the disabled active-command '
                    'window; normal FSM timing progressed while ena was low')

    enabled_progress = False
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        cur = trace[i]
        if (prev.get('inputs', {}).get('ena') == 1 and
                cur.get('inputs', {}).get('ena') == 1 and
                out(prev, 'active_command') == 1 and
                out(cur, 'active_command') == 1 and
                out(prev, 'cmd_ack') != 1 and
                out(cur, 'cmd_ack') != 1 and
                out(prev, 'scl_oen') != out(cur, 'scl_oen')):
            enabled_progress = True
            break

    if not enabled_progress:
        return (None, None,
                'disabled active-command window was observed, but the routed '
                'normal enabled timing path was not exercised')

    return (True, disabled_rows[0].get('edge'),
            'scl_oen remained at its current timed FSM phase while ena was '
            'low during an active command')

