def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def holds(cond):
        def predicate(row):
            return all(
                row.get('outputs', {}).get(port,
                    row.get('inputs', {}).get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_of(alternatives):
        predicates = [holds(alt) for alt in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    activation = lambda row: (
        row.get('outputs', {}).get('write_stable_high_phase') == 1
    )
    aborts = any_of([
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        activation,
        until=holds({'cmd_ack': 1}),
        aborts=aborts,
    )

    low_sda = []
    high_sda = []
    for window in windows:
        if (window.value('din') == 1 and
                window.value('sda_oen') == 1):
            if window.value('sda_i') == 0:
                low_sda.append(window)
            elif window.value('sda_i') == 1:
                high_sda.append(window)

    verdicts = []
    follows = True
    for window in low_sda:
        verdicts.append(eventually(
            window,
            lambda row: row.get('outputs', {}).get('al') == 1,
            strong=True,
            after_activation=follows,
        ))

    for window in high_sda:
        verdicts.append(throughout(
            window,
            lambda row: row.get('outputs', {}).get('al') == 0,
            after_activation=follows,
        ))

    if not verdicts:
        return (None, None, 'no enabled WRITE stable-high arbitration-signature case occurred')

    result = worst(verdicts)
    if result[0] is False:
        return result

    if not low_sda or not high_sda:
        return (None, result[1],
                'only one routed case was exercised; both filtered-SDA low and high cases are required to distinguish arbitration checking')

    return (True, result[1],
            'during the WRITE stable-high phase, SDA-low asserted al and SDA-high left al deasserted')

