                       for port, value in cond.items())
        return predicate

    def any_of(alternatives):
        predicates = [holds(alt) for alt in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The declared probe directly names the situation in the obligation.
    windows = after(
        trace,
        holds({'write_stable_high_phase': 1}),
        until=holds({'cmd_ack': 1}),
        aborts=any_of([
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    low_cases = []
    high_cases = []
    for window in windows:
        rows = window.rows
        low_seen = any(
            row.get('inputs', {}).get('sda_i') == 0 and
            row.get('outputs', {}).get('sda_oen') == 1
            for row in rows
        )
        high_seen = any(
            row.get('inputs', {}).get('sda_i') == 1 and
            row.get('outputs', {}).get('sda_oen') == 1
            for row in rows
        )
        if low_seen:
            low_cases.append(window)
        if high_seen:
            high_cases.append(window)

