                row.get('inputs', {}).get('sda_i') != 1 or
                row.get('outputs', {}).get('sda_oen') != 1 or
                row.get('outputs', {}).get('al') == 0
            ),
            after_activation=follows,
        ))

    result = worst(verdicts)
    if result[0] is False:
        return result

    if not low_cases or not high_cases:
        return (None, result[1],
