def decide(trace):
    from specflow.refmodel.temporal import TO_END, after

    def applies(row):
        return (row['inputs'].get('cmd') == 4 and
                row['inputs'].get('din') == 1 and
                row['inputs'].get('ena') == 1 and
                row['outputs'].get('sda_oen') == 1)

    windows = after(trace, applies, until=TO_END)
    al_rises = set()
    previous = None
    for row in trace:
        value = row['outputs'].get('al')
        if value == 1 and previous == 0:
            al_rises.add(row['edge'])
        previous = value

    saw_condition = False
    for window in windows:
        condition_row = None
        for row in window.rows:
            if (row['outputs'].get('sda_oen') == 1 and
                    row['inputs'].get('sda_i') == 0):
                condition_row = row
                break
        if condition_row is None:
            continue

        saw_condition = True
        if condition_row['outputs'].get('al') == 1:
            return (True, condition_row['edge'],
                    'al was already asserted when SDA was observed low while sda_oen was high')

        for row in trace:
            if row['edge'] > condition_row['edge'] and row['edge'] in al_rises:
                return (True, row['edge'],
                        'al asserted after SDA was observed low while sda_oen was high')

        return (False, condition_row['edge'],
                'al did not assert after SDA was observed low while sda_oen was high')

    if not windows or not saw_condition:
        return (None, None,
                'the enabled high-data WRITE did not expose SDA low while sda_oen was high')

    return (None, None, 'no qualifying arbitration-loss observation')

