    from specflow.refmodel.temporal import after, edges, worst

    def in_arbitration_phase(row):
        return (row['inputs'].get('cmd') == 4 and
                row['inputs'].get('din') == 1 and
                row['inputs'].get('ena') == 1 and
                row['outputs'].get('arbitration_checking') == 1 and
                row['outputs'].get('sda_oen') == 1)

    windows = after(trace, in_arbitration_phase, until=__import__('specflow.refmodel.temporal', fromlist=['TO_END']).TO_END)
    al_rises = edges(trace, 'al', 'rise')
    verdicts = []

    for window in windows:
        if not any(row['inputs'].get('sda_i') == 0 for row in window.rows):
            continue

        rise_in_phase = [row for row in window.rows if row['edge'] in al_rises]
        if rise_in_phase:
            verdicts.append((True, rise_in_phase[0]['edge'],
                             'al asserted during the released-high arbitration-checking phase after SDA was observed low'))
        elif window.rows and window.rows[0]['outputs'].get('al') == 1:
            verdicts.append((None, window.rows[0]['edge'],
