        return row['outputs'].get(port)

    def reset(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    def active(row):
        return value(row, 'active_command') == 1

    def active_end(row):
        return not active(row)

    def unexpected_stop(row):
        return (
            active(row)
            and value(row, 'stop_condition') == 1
            and value(row, 'in_stop_sequence') != 1
        )

    def completion(row):
