def decide(trace):
    # The obligation is not mechanically observable with the supplied contract:
    # cmd symbols have no authoritative encoding table, and the routed output
    # signature belongs to REQ-0007 rather than stating this requirement's own
    # concrete effect.
    for row in trace:
        row.get('inputs', {}).get('cmd')
        row.get('outputs', {}).get('sda_oen')
    return (None, None, 'undecidable: cmd has no licensed symbol-to-integer encoding and this obligation supplies no direct output effect')

def decide(trace):
    CMD = {1: 'START', 2: 'STOP', 8: 'READ', 4: 'WRITE', 0: 'NOP'}

    def out(row, name):
        return row.get('outputs', {}).get(name)

    windows = []
    active = False
    start = None
    for i, row in enumerate(trace):
        idle = out(row, 'in_idle') == 1
        cmd = row.get('inputs', {}).get('cmd')
        applies = idle and cmd in CMD
        if applies and not active:
            active = True
            start = i
        elif active and not idle:
            windows.append((start, i, True))
            active = False
            start = None
    if active:
        windows.append((start, len(trace), False))

    if not windows:
        return (None, None, 'the idle decoding situation never occurred')

    for start, stop, closed in windows:
        row0 = trace[start]
        cmd = row0.get('inputs', {}).get('cmd')
        name = CMD.get(cmd)
        rows = trace[start + 1:stop]
        if not rows:
            continue

        values = [out(r, 'sda_oen') for r in rows]
        bad_edge = None

        if name == 'START':
            saw_release = out(row0, 'sda_oen') == 1
            drove_low = False
            for j, r in enumerate(rows):
                if saw_release and out(r, 'sda_oen') == 0:
                    drove_low = True
                    break
                if out(r, 'sda_oen') == 1:
                    saw_release = True
            if not drove_low:
                if closed:
                    bad_edge = trace[stop - 1]['edge']
                    return (False, bad_edge, 'START decoding did not produce the stated release-then-drive-low sda_oen signature')
                continue

        elif name == 'STOP':
            drove_low = False
            released = False
            for r in rows:
                v = out(r, 'sda_oen')
                if not drove_low and v == 0:
                    drove_low = True
                elif drove_low and v == 1:
                    released = True
                    break
            if not released:
                if closed:
                    bad_edge = trace[stop - 1]['edge']
                    return (False, bad_edge, 'STOP decoding did not produce the stated drive-low-then-release sda_oen signature')
                continue

        elif name == 'READ':
            if any(v != 1 for v in values):
                bad = next(r for r in rows if out(r, 'sda_oen') != 1)
                return (False, bad['edge'], 'READ decoding did not keep sda_oen released')

        elif name == 'WRITE':
            din = row0.get('inputs', {}).get('din')
            expected = 0 if din == 0 else 1
            if din not in (0, 1):
                continue
            if expected not in values:
                if closed:
                    bad_edge = trace[stop - 1]['edge']
                    return (False, bad_edge, f'WRITE decoding did not produce the sda_oen signature required by din={din}')
                continue

        elif name == 'NOP':
            bad = next((r for r in rows if out(r, 'sda_oen') != 1), None)
            if bad is not None:
                return (False, bad['edge'], 'no-operation decoding produced a command signature instead of leaving sda_oen released')

        if not closed:
            continue
        return (True, trace[stop - 1]['edge'], f'{name} command decoded with the corresponding sda_oen signature')

    return (None, None, 'idle decoding window was opened but the trace ended before its command signature was decided')

def decide(trace):
    CMD = {1: 'START', 2: 'STOP', 8: 'READ', 4: 'WRITE', 0: 'NOP'}

    def value(row, name):
        return row.get('outputs', {}).get(name)

    def applies(row):
        return (value(row, 'in_idle') == 1
                and row.get('inputs', {}).get('ena') == 1
                and value(row, 'clk_en_tick') == 1
                and row.get('inputs', {}).get('cmd') in CMD)

    windows = []
    previous = False
    for i, row in enumerate(trace):
        now = applies(row)
        if now and not previous:
            cmd = row.get('inputs', {}).get('cmd')
            end = None
            for j in range(i + 1, len(trace)):
                if value(trace[j], 'in_idle') == 0:
                    end = j
                    break
            windows.append((i, end))
        previous = now

    if not windows:
        return (None, None, 'the idle decoding situation never occurred')

    for start, end in windows:
        command = CMD[trace[start].get('inputs', {}).get('cmd')]
        last = end if end is not None else len(trace)
        rows = trace[start + 1:last]

        def transitions_to(target):
            for j, row in enumerate(rows, start + 1):
                before = value(trace[j - 1], 'sda_oen')
                after = value(row, 'sda_oen')
                if before != target and after == target:
                    return row
            return None

        if command == 'START':
            low = transitions_to(0)
            if low is None:
                if end is None:
                    continue
                return (False, trace[end - 1]['edge'],
                        'START decoding did not transition sda_oen into the driven-low phase')
            return (True, low['edge'],
                    'START decoding produced the required sda_oen drive-low phase')

        if command == 'STOP':
            low = transitions_to(0)
            if low is None:
                if end is None:
                    continue
                return (False, trace[end - 1]['edge'],
                        'STOP decoding did not transition sda_oen into the driven-low phase')
            released = None
            for j in range(rows.index(low) + 1, len(rows)):
                before = value(trace[start + 1 + j - 1], 'sda_oen')
                after = value(rows[j], 'sda_oen')
                if before == 0 and after == 1:
                    released = rows[j]
                    break
            if released is None:
                if end is None:
                    continue
                return (False, trace[end - 1]['edge'],
                        'STOP decoding did not transition sda_oen back to released after driving low')
            return (True, released['edge'],
                    'STOP decoding produced the required drive-low-then-release sda_oen signature')

        if command == 'WRITE':
            din = trace[start].get('inputs', {}).get('din')
            if din == 0:
                low = transitions_to(0)
                if low is not None:
                    return (True, low['edge'],
                            'WRITE decoding with din=0 transitioned sda_oen into the required driven-low state')
                if end is None:
                    continue
                return (False, trace[end - 1]['edge'],
                        'WRITE decoding with din=0 did not produce the required driven-low sda_oen state')
            if din == 1:
                low = transitions_to(0)
                if low is not None:
                    return (False, low['edge'],
                            'WRITE decoding with din=1 drove sda_oen low instead of releasing SDA')
                return (None, None,
                        'WRITE decoding with din=1 is indistinguishable on sda_oen from its ordinary released idle behavior')
            return (None, None, 'WRITE command occurred without a determinate din qualifier')

        if command == 'READ':
            bad = next((r for r in rows if value(r, 'sda_oen') != 1), None)
            if bad is not None:
                return (False, bad['edge'],
                        'READ decoding drove sda_oen instead of keeping SDA released')
            return (None, None,
                    'READ decoding is not distinguishable from ordinary released sda_oen behavior on this routed port')

        if command == 'NOP':
            bad = next((r for r in rows if value(r, 'sda_oen') != 1), None)
            if bad is not None:
                return (False, bad['edge'],
                        'no-operation decoding produced a command sda_oen waveform')
            return (True, trace[start]['edge'],
                    'no-operation command was accepted while idle without a sda_oen command sequence')

    return (None, None, 'the idle decoding window opened but the trace ended before its routed command signature was decided')

