from specflow.refmodel.temporal import after, sequence, worst


def _holds(cond):
    def predicate(row):
        return all(
            row.get("outputs", {}).get(port, row.get("inputs", {}).get(port)) == value
            for port, value in cond.items()
        )
    return predicate


def _any(alternatives):
    predicates = [_holds(condition) for condition in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    # The command encoding is unspecified; the declared probe identifies the
    # START-command sequence without inventing a numeric cmd value.
    start_sequence = _holds({"in_start_sequence": 1})
    aborts = _any([{"nReset": 0}, {"rst": 1}])

    windows = after(
        trace,
        start_sequence,
        until=_holds({"scl_oen": 1, "sda_oen": 0}),
        aborts=aborts,
    )

    released = _holds({"scl_oen": 1, "sda_oen": 1})
    start_phase = _holds({"scl_oen": 1, "sda_oen": 0})

    return worst([
        sequence(
            window,
            released,
            start_phase,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    def out(row, name):
        return row.get("outputs", {}).get(name)

    def reset_active(row):
        return (row.get("inputs", {}).get("nReset") == 0 or
                row.get("inputs", {}).get("rst") == 1)

    activations = []
    for i, row in enumerate(trace):
        now = out(row, "in_start_sequence") == 1
        before = (i > 0 and
                  out(trace[i - 1], "in_start_sequence") == 1)
        if now and not before:
            activations.append(i)

    if not activations:
        return (None, None,
                "START sequence never began; no START-command situation was exercised")

    for start_i in activations:
        for i in range(start_i + 1, len(trace)):
            if reset_active(trace[i]):
                break

            previous = trace[i - 1]
            current = trace[i]
            sda_fell = (out(previous, "sda_oen") == 1 and
                        out(current, "sda_oen") == 0)
            scl_remained_released = (out(previous, "scl_oen") == 1 and
                                     out(current, "scl_oen") == 1)
            if sda_fell and scl_remained_released:
                return (True, current["edge"],
                        "during the START sequence, sda_oen changed from released 1 to driven-low 0 while scl_oen remained released 1")

        for i in range(start_i + 1, len(trace)):
            if reset_active(trace[i]):
                return (None, trace[i]["edge"],
                        "START sequence was aborted by reset before the required SDA-low transition")

        return (False, trace[start_i]["edge"],
                "START sequence began but sda_oen never transitioned from 1 to 0 while scl_oen remained 1")

    return (None, None, "no START sequence was evaluated")

