from specflow.refmodel.temporal import TO_END, after, edges, eventually, pulse, worst


def _holds(cond):
    def pred(row):
        return all(
            row["outputs"].get(port, row["inputs"].get(port)) == value
            for port, value in cond.items()
        )
    return pred


def decide(trace):
    # The port has no authoritative symbol-to-integer encoding table.  Use the
    # declared START-sequence probe to qualify which idle transition belongs to
    # this requirement, rather than inventing a numeric cmd encoding.
    idle_rises = edges(trace, "in_idle", "rise")
    start_seen = set()
    seen_start_sequence = False
    for row in trace:
        if row["outputs"].get("in_start_sequence") == 1:
            seen_start_sequence = True
        if seen_start_sequence and row["edge"] in idle_rises:
            start_seen.add(row["edge"])

    opens = after(
        trace,
        lambda row: row["edge"] in start_seen
        and row["outputs"].get("in_idle") == 1,
        until=_holds({"cmd_ack": 1}),
        aborts=lambda row: (
            row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
        ),
    )

    follows = False
    verdicts = []
    for window in opens:
        verdicts.append(
            eventually(
                window,
                lambda row: row["outputs"].get("scl_oen") == 0,
                strong=True,
                after_activation=follows,
            )
        )
        verdicts.append(
            eventually(
                window,
                lambda row: row["outputs"].get("in_idle") == 1,
                strong=True,
                after_activation=follows,
            )
        )
        verdicts.append(
            pulse(
                window,
                "cmd_ack",
                width=1,
                active=1,
                after_activation=follows,
            )
        )

    return worst(verdicts)

