        if completion[0] is False:
            return completion
        if completion[0] is None:
            verdicts.append(completion)
            continue

        window_edges = {row['edge'] for row in w.rows}
        ack_edges = [
            row['edge'] for row in w.rows
            if row['outputs'].get('cmd_ack') == 1
        ]
        matching_pulses = {
            edge for edge in exact_pulses
            if edge in window_edges and edge > w.edge
        }

        if not matching_pulses:
            if ack_edges:
                return (
                    False,
                    ack_edges[0],
                    "cmd_ack did not form a one-clock pulse; the requirement states that it 'pulses cmd_ack'"
                )
            verdicts.append((None, w.edge, 'STOP completion pulse evidence was incomplete'))
            continue

        verdicts.append((
            True,
            min(matching_pulses),
            "STOP completion returned the FSM to idle and cmd_ack pulsed for exactly one clock"
        ))

    return worst(verdicts)

