def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        # Leaving the declared READ-sequence probe is the observable
        # signature of the READ bit cycle completing.  Do not encode READ
        # as a bare cmd number because no cmd encoding table is supplied.
        if (prev_out.get('in_read_sequence') == 1
                and out.get('in_read_sequence') != 1
                and row.get('inputs', {}).get('ena') == 1):
            completions.append(row)

    if not completions:
        return (None, None, 'no completed READ bit cycle was observed')

    for row in completions:
        out = row.get('outputs', {})
        if out.get('in_idle') != 1 or out.get('cmd_ack') != 1:
            missing = []
            if out.get('in_idle') != 1:
                missing.append('in_idle')
            if out.get('cmd_ack') != 1:
                missing.append('cmd_ack')
            return (False, row.get('edge'),
                    'after the READ bit cycle completed, required effect(s) '
                    'were not present: ' + ', '.join(missing))

    return (True, completions[-1].get('edge'),
            'each observed completed READ bit cycle returned to idle and asserted cmd_ack')

