def decide(trace):
    # The command encoding is not stated in an authoritative port encoding
    # table, so use the declared WRITE-phase probe instead of guessing cmd's
    # numeric encoding.
    def aborted(row):
        return (
            row['outputs'].get('al') == 1
            or row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    starts = []
    previous = False
    for i, row in enumerate(trace):
        active = row['outputs'].get('in_write_sequence') == 1
        if active and not previous:
            starts.append(i)
        previous = active

    if not starts:
        return (None, None, 'the declared WRITE-phase signature never occurred')

    saw_nonaborted = False
    for start in starts:
        din_value = trace[start]['inputs'].get('din')
        end = start
        while end < len(trace) and trace[end]['outputs'].get('in_write_sequence') == 1:
            end += 1

        rows = trace[start:end]
        if any(aborted(row) for row in rows):
            continue

        saw_nonaborted = True
        expected = 0 if din_value == 0 else 1
        for row in rows:
            actual = row['outputs'].get('sda_oen')
            if actual != expected:
                meaning = 'driving SDA low' if expected == 0 else 'releasing SDA high'
                return (
                    False,
                    row['edge'],
                    f"during the WRITE phase, din was {din_value} but sda_oen was {actual}; expected {expected} ({meaning})"
                )

    if not saw_nonaborted:
        return (None, None, 'all observed WRITE phases were aborted by reset or arbitration loss')

    return (True, None, 'sda_oen matched din throughout each non-aborted WRITE phase')

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def any_condition(alternatives):
        def predicate(row):
            for condition in alternatives:
                if all(
                    row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items()
                ):
                    return True
            return False
        return predicate

    # Open only when the declared WRITE phase begins, not while the stimulus
    # continues to hold the command input.
    write_starts = set()
    was_in_write = False
    for row in trace:
        in_write = row['outputs'].get('in_write_sequence') == 1
        if in_write and not was_in_write:
            write_starts.add(row['edge'])
        was_in_write = in_write

    if not write_starts:
        return (None, None, 'the declared WRITE-phase signature never occurred')

    # An action requires a transition into the selected open-drain enable
    # value, rather than merely observing the same value already held in idle.
    transitions_into = {0: set(), 1: set()}
    for i in range(1, len(trace)):
        previous = trace[i - 1]['outputs'].get('sda_oen')
        current = trace[i]['outputs'].get('sda_oen')
        if current in (0, 1) and previous != current:
            transitions_into[current].add(trace[i]['edge'])

    windows = after(
        trace,
        lambda row: row['edge'] in write_starts,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    follows = True
    verdicts = []
    for window in windows:
        din_value = window.value('din')
        expected = 0 if din_value == 0 else 1
        meaning = 'driving SDA low' if expected == 0 else 'releasing SDA high'
        verdicts.append(
            eventually(
                window,
                lambda row, expected=expected: (
                    row['outputs'].get('sda_oen') == expected
                    and row['edge'] in transitions_into[expected]
                ),
                after_activation=follows,
                strong=False,
            )
        )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def aborts(row):
        outputs = row['outputs']
        inputs = row['inputs']
        return (
            outputs.get('al') == 1
            or inputs.get('nReset') == 0
            or inputs.get('rst') == 1
        )

