def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, worst

    def holds(cond):
        def predicate(row):
            outputs = row.get('outputs', {})
            inputs = row.get('inputs', {})
            return all(outputs.get(k, inputs.get(k)) == v
                       for k, v in cond.items())
        return predicate

    def any_of(alternatives):
        predicates = [holds(a) for a in alternatives]
        return lambda row: any(p(row) for p in predicates)

    def applies(row):
        return (row.get('inputs', {}).get('ena') == 1 and
                row.get('outputs', {}).get('in_write_sequence') == 1)

    aborts = any_of([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        applies,
        until=holds({'cmd_ack': 1}),
        aborts=aborts,
    )

    if not windows:
        return (None, None, 'the WRITE activation never occurred')

    def value(row, port):
        return row.get('outputs', {}).get(port)

    def changed_into(index, port, target):
        if index <= 0:
            return False
        return (value(trace[index], port) == target and
                value(trace[index - 1], port) != target)

    verdicts = []
    for window in windows:
        opened = window.rows[0].get('index', 0) if window.rows else 0
        first_after = opened + 1

        high_index = None
        for index in range(first_after, len(trace)):
            if changed_into(index, 'scl_oen', 1):
                high_index = index
                break

        if high_index is None:
            verdicts.append((False, window.edge,
                             'scl_oen did not transition into released-high during the WRITE sequence'))
            continue

        low_index = None
        stable_index = None
        for index in range(high_index, len(trace)):
            if value(trace[index], 'write_stable_high_phase') == 1:
                stable_index = index
            if index > high_index and changed_into(index, 'scl_oen', 0):
                low_index = index
                break

        if stable_index is None or low_index is None or stable_index >= low_index:
            verdicts.append((False, trace[high_index].get('edge'),
                             'scl_oen did not remain released through a stable WRITE high phase before transitioning low'))
            continue

        idle_index = next(
            (index for index in range(low_index + 1, len(trace))
             if value(trace[index], 'in_idle') == 1),
            None)
        if idle_index is None:
            verdicts.append((False, trace[low_index].get('edge'),
                             'the FSM did not return to idle after pulling SCL low'))
            continue

        ack_index = next(
            (index for index in range(low_index + 1, len(trace))
             if value(trace[index], 'cmd_ack') == 1),
            None)
        if ack_index is None:
            verdicts.append((False, trace[low_index].get('edge'),
                             'cmd_ack did not pulse after the WRITE low phase'))
            continue

        pulse_edges = 0
        index = ack_index
        while index < len(trace) and value(trace[index], 'cmd_ack') == 1:
            pulse_edges += trace[index].get('held', 1)
            index += 1

        if index == len(trace):
            verdicts.append((None, trace[ack_index].get('edge'),
                             'cmd_ack was still high at trace end, so its one-clock pulse could not be closed'))
        elif pulse_edges != 1:
            verdicts.append((False, trace[ack_index].get('edge'),
                             f'cmd_ack was high for {pulse_edges} edges, expected exactly one clock'))
        else:
            verdicts.append((True, trace[ack_index].get('edge'),
                             'scl_oen transitioned high during the stable WRITE phase, then low; the FSM returned idle and cmd_ack pulsed for one clock'))

    return worst(verdicts)

