def decide(trace):
    valid_cmds = (1, 2, 8, 4)

    def sequence_active(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(p, 0) == 1 for p in (
            'in_start_sequence',
            'in_stop_sequence',
            'in_read_sequence',
            'in_write_sequence',
        ))

    def applies(row):
        inputs = row.get('inputs', {})
        return (
            inputs.get('cmd') in valid_cmds
            and inputs.get('ena') == 1
            and sequence_active(row)
        )

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    windows = after(
        trace,
        applies,
        until=lambda r: r.get('outputs', {}).get('cmd_ack') == 1,
        aborts=reset_active,
    )

    verdicts = []
    for window in windows:
        arrival = eventually(
            window,
            lambda r: r.get('outputs', {}).get('cmd_ack') == 1,
            strong=True,
            after_activation=True,
        )
        if arrival[0] is not True:
            verdicts.append(arrival)
            continue

        ack_row = next(
            r for r in window.rows
            if r.get('outputs', {}).get('cmd_ack') == 1
        )
        ack_pos = ack_row['index']
        high_edges = 0
        pos = ack_pos
        while pos < len(trace):
            row = trace[pos]
            if row.get('outputs', {}).get('cmd_ack') != 1:
                break
            high_edges += row.get('held', 1)
            pos += 1

        if high_edges != 1:
            verdicts.append((
                False,
                ack_row.get('edge'),
                f"cmd_ack was high for {high_edges} edges; the requirement says 'asserted for exactly one `clk` cycle'",
            ))
        elif pos >= len(trace):
            verdicts.append((
                None,
                ack_row.get('edge'),
                "cmd_ack completed a one-edge observed pulse, but the trace ended before its return low",
            ))
        else:
            verdicts.append((
                True,
                ack_row.get('edge'),
                "cmd_ack was high for exactly one `clk` cycle at sequence completion and then returned low",
            ))

    return worst(verdicts)

