def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    sequence_probes = (
        "in_start_sequence",
        "in_stop_sequence",
        "in_read_sequence",
        "in_write_sequence",
    )
    completion_edges = set()
    for probe in sequence_probes:
        completion_edges.update(edges(trace, probe, "fall"))

    def completion_boundary(row):
        return row["edge"] in completion_edges

    def reset_active(row):
        inputs = row.get("inputs", {})
        return inputs.get("nReset") == 0 or inputs.get("rst") == 1

    windows = after(
        trace,
        completion_boundary,
        until=TO_END,
        aborts=reset_active,
    )

    verdicts = []
    for window in windows:
        seen = eventually(
            window,
            lambda row: row.get("outputs", {}).get("cmd_ack") == 1,
            after_activation=False,
            strong=True,
        )
        if seen[0] is not True:
            verdicts.append(seen)
            continue

        ack_rows = [
            row for row in window.rows
            if row.get("outputs", {}).get("cmd_ack") == 1
        ]
        width = sum(row.get("held", 1) for row in ack_rows)
        if width != 1:
            edge = ack_rows[0]["edge"] if ack_rows else window.edge
            verdicts.append(
                (False, edge,
                 f"cmd_ack acknowledge pulse lasted {width} clock edge(s), expected exactly one")
            )
        else:
            verdicts.append(
                (True, ack_rows[0]["edge"],
                 "cmd_ack asserted for exactly one clock edge at sequence completion")
            )

    return worst(verdicts)

